import type { ClassValue } from 'clsx'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'
import { joinURL } from 'ufo'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export const objectToFlatString = (obj: object | string, _prefix?: string): string => {
  if (typeof obj === 'string') {
    return obj
  }
  const key = Object.keys(obj)[0] as keyof typeof obj
  const value = obj[key]

  const prefix = _prefix ? `${_prefix}.` : ''
  if (typeof value === 'object') {
    return objectToFlatString(value, `${prefix}${key}`)
  }
  return `${prefix}${key}.${value}`
}

export const resolveInternalLink = (url: string) => joinURL(import.meta.env.BASE_URL, url)
