import { onBeforeUnmount, onMounted, ref, type Ref } from 'vue'

import { suspenseAudioController } from './suspenseAudioController'

type InputSource = 'pointer' | 'keyboard'

type HoldToPlayOptions = {
  loopRef: Ref<HTMLAudioElement | null>
  endingRef?: Ref<HTMLAudioElement | null>
  registerController?: boolean
  controller?: typeof suspenseAudioController
}

type ReleaseOptions = {
  playEnding?: boolean
}

export const useHoldToPlayAudio = ({
  loopRef,
  endingRef,
  registerController = false,
  controller = suspenseAudioController,
}: HoldToPlayOptions) => {
  const isHolding = ref(false)
  const activePointerId = ref<number | null>(null)
  const activeInput = ref<InputSource | null>(null)
  let unregisterController: (() => void) | null = null

  const safePlay = (audio: HTMLAudioElement | null) => {
    if (!audio) {
      return
    }
    const playPromise = audio.play()
    if (playPromise) {
      playPromise.catch(() => {
        // Playback can be interrupted by the browser; ignore.
      })
    }
  }

  const stopAndReset = (audio: HTMLAudioElement | null) => {
    if (!audio) {
      return
    }
    audio.pause()
    try {
      audio.currentTime = 0
    } catch {
      audio.load()
    }
  }

  const startLoop = () => {
    if (endingRef?.value) {
      stopAndReset(endingRef.value)
    }
    const loop = loopRef.value
    if (!loop) {
      return
    }
    loop.currentTime = 0
    safePlay(loop)
  }

  const stopLoop = () => {
    stopAndReset(loopRef.value)
  }

  const playEnding = () => {
    const ending = endingRef?.value
    if (!ending) {
      return
    }
    stopAndReset(ending)
    safePlay(ending)
  }

  const releaseHold = (options: ReleaseOptions = {}) => {
    if (!isHolding.value) {
      return false
    }

    const defaultPlayEnding = Boolean(endingRef?.value)
    const { playEnding: shouldPlayEnding = defaultPlayEnding } = options

    isHolding.value = false
    activeInput.value = null
    stopLoop()

    if (shouldPlayEnding) {
      playEnding()
    } else if (endingRef?.value) {
      stopAndReset(endingRef.value)
    }

    return true
  }

  const engageHold = (input: InputSource) => {
    if (isHolding.value) {
      return false
    }
    activeInput.value = input
    isHolding.value = true
    startLoop()
    return true
  }

  const handlePointerDown = (event: PointerEvent) => {
    if (activePointerId.value !== null && activePointerId.value !== event.pointerId) {
      return
    }
    activePointerId.value = event.pointerId
    ;(event.currentTarget as HTMLElement | null)?.setPointerCapture?.(event.pointerId)
    engageHold('pointer')
  }

  const handlePointerUp = (event: PointerEvent) => {
    if (activePointerId.value !== event.pointerId) {
      return
    }
    activePointerId.value = null
    ;(event.currentTarget as HTMLElement | null)?.releasePointerCapture?.(event.pointerId)
    releaseHold()
  }

  const handlePointerCancel = (event: PointerEvent) => {
    if (activePointerId.value !== event.pointerId) {
      return
    }
    activePointerId.value = null
    releaseHold()
  }

  const handlePointerLeave = (event: PointerEvent) => {
    if (activePointerId.value !== event.pointerId) {
      return
    }
    activePointerId.value = null
    releaseHold()
  }

  const handleKeyDown = () => {
    if (activeInput.value && activeInput.value !== 'keyboard') {
      return
    }
    engageHold('keyboard')
  }

  const handleKeyUp = () => {
    if (activeInput.value !== 'keyboard') {
      return
    }
    releaseHold()
  }

  const handleBlur = () => {
    releaseHold({ playEnding: false })
    activePointerId.value = null
  }

  onMounted(() => {
    if (!registerController) {
      return
    }
    unregisterController = controller.register({
      engage: () => engageHold('keyboard'),
      release: (options) => releaseHold(options ?? {}),
      cancel: () => releaseHold({ playEnding: false }),
      isActive: () => isHolding.value,
    })
  })

  onBeforeUnmount(() => {
    releaseHold({ playEnding: false })
    activePointerId.value = null
    if (unregisterController) {
      unregisterController()
      unregisterController = null
    }
  })

  return {
    isHolding,
    handlePointerDown,
    handlePointerUp,
    handlePointerCancel,
    handlePointerLeave,
    handleKeyDown,
    handleKeyUp,
    handleBlur,
    engageHold,
    releaseHold,
  }
}
