<template>
  <footer class="flex w-full justify-center pb-4">
    <div
      class="flex w-full flex-col flex-wrap items-center justify-center gap-y-1 md:w-2/3 lg:w-1/2 xl:w-1/3 2xl:w-1/4"
    >
      <div class="grid w-full gap-2">
        <Button
          v-if="isVotingResults"
          type="button"
          :variant="killCandidatesCount > 1 ? 'default' : 'outline'"
          class="w-full"
          @click="emit('return-to-monologues')"
        >
          <Icon title="icon-[tabler--arrow-back]" class="size-4"></Icon>
          Вернуться к монологам
        </Button>
        <Button
          v-if="isNightRoleTurn"
          type="button"
          class="inline-flex items-center gap-2 rounded-md bg-slate-800 px-4 py-2 text-sm font-medium text-slate-200 transition hover:bg-slate-700"
          @click="emit('complete-night-role')"
        >
          Завершить ход роли
          <Icon title="icon-[tabler--arrow-right]" class="size-4"></Icon>
        </Button>
        <Button
          v-if="isEliminationConfirmationNeeded"
          type="button"
          class="w-full"
          @click="emit('confirm-elimination')"
        >
          Подтвердить выбывание
        </Button>
        <Button
          v-if="isMonologues"
          type="button"
          class="w-full"
          variant="outline"
          :disabled="!hasEligibleSpeakers"
          @click="emit('choose-random-speaker')"
        >
          Случайный спикер
          <Icon title="icon-[tabler--dice-5-filled]" class="size-4"></Icon>
        </Button>
        <Button
          v-if="canRestartNight"
          type="button"
          variant="outline"
          class="w-full"
          @click="emit('restart-night')"
        >
          <Icon title="icon-[tabler--arrow-back]" class="size-4"></Icon>
          Повторить ночь
        </Button>
        <Button
          v-if="canContinue && !isGameOver && !isEliminationConfirmationNeeded"
          type="button"
          :variant="isVotingResults && killCandidatesCount > 1 ? 'outline' : 'default'"
          class="w-full dark:bg-slate-800 dark:text-white dark:hover:bg-slate-700"
          @click="emit('continue-stage')"
        >
          {{ nextButtonText }}
          <Icon title="icon-[tabler--arrow-right]" class="size-4"></Icon>
        </Button>
      </div>
    </div>
  </footer>
</template>

<script setup lang="ts">
import { Button } from '@shared/ui/button'

defineProps<{
  isVotingResults: boolean
  isNightRoleTurn: boolean
  isEliminationConfirmationNeeded: boolean
  canResetToDiscussion: boolean
  isMonologues: boolean
  hasEligibleSpeakers: boolean
  canContinue: boolean
  canRestartNight: boolean
  isGameOver: boolean
  killCandidatesCount: number
  nextButtonText: string | undefined
}>()

const emit = defineEmits<{
  (e: 'return-to-monologues'): void
  (e: 'complete-night-role'): void
  (e: 'confirm-elimination'): void
  (e: 'reset-to-discussion'): void
  (e: 'choose-random-speaker'): void
  (e: 'continue-stage'): void
  (e: 'restart-night'): void
}>()
</script>
