type AudioSource = () => HTMLAudioElement | null

const noop = () => undefined

let currentSource: AudioSource | null = null

const getAudio = () => (currentSource ? currentSource() : null)

const safePlay = (audio: HTMLAudioElement) => {
  const playPromise = audio.play()
  if (playPromise) {
    playPromise.catch(noop)
  }
}

export const audioController = {
  register(source: AudioSource) {
    currentSource = source
    return () => {
      if (currentSource === source) {
        currentSource = null
      }
    }
  },
  restart() {
    const audio = getAudio()
    if (!audio) {
      return false
    }
    audio.currentTime = 0
    safePlay(audio)
    return true
  },
  togglePlayback() {
    const audio = getAudio()
    if (!audio) {
      return false
    }
    if (audio.paused) {
      safePlay(audio)
    } else {
      audio.pause()
    }
    return true
  },
  pause() {
    const audio = getAudio()
    if (!audio) {
      return false
    }
    audio.pause()
    return true
  },
  play() {
    const audio = getAudio()
    if (!audio) {
      return false
    }
    safePlay(audio)
    return true
  },
}
