<template>
  <RouterView />
</template>

<script setup lang="ts">
import { RouterView, useRoute } from 'vue-router'
import { ref, watch } from 'vue'

import { useGameStore } from './stores/gameStore'
import { decodeSnapshot } from '@shared/lib/snapshotLink'
import { gameSessionStorage } from '@shared'
import type { PersistedGameSession } from '@shared'

const gameStore = useGameStore()
const route = useRoute()

const lastAppliedSnapshot = ref<string | null>(null)
const hasInitializedSession = ref(false)

const applySession = (session: PersistedGameSession) => {
  gameStore.restoreFromSnapshot(session)
  hasInitializedSession.value = true
}

const normalizeSnapshotParam = (value: unknown): string | null => {
  if (typeof value === 'string' && value.length) {
    return value
  }
  if (Array.isArray(value) && value.length) {
    const [first] = value
    return typeof first === 'string' && first.length ? first : null
  }
  return null
}

const tryRestoreFromSnapshot = (encoded: string | null): boolean => {
  if (!encoded || encoded === lastAppliedSnapshot.value) {
    return false
  }

  const snapshot = decodeSnapshot(encoded)
  if (!snapshot) {
    return false
  }

  applySession(snapshot)
  lastAppliedSnapshot.value = encoded

  return true
}

const tryRestoreFromStorage = () => {
  if (hasInitializedSession.value) {
    return
  }

  const persisted = gameSessionStorage.load()
  if (persisted) {
    applySession(persisted)
  }
}

const initialSnapshot = normalizeSnapshotParam(route.query.snapshot)
const restoredFromSnapshot = tryRestoreFromSnapshot(initialSnapshot)

if (!restoredFromSnapshot) {
  tryRestoreFromStorage()
}

watch(
  () => normalizeSnapshotParam(route.query.snapshot),
  (encoded) => {
    tryRestoreFromSnapshot(encoded)
  },
)
</script>
