<template>
  <Dialog :open="gameHistory.isDialogOpen" @update:open="gameHistory.handleDialogToggle">
    <DialogContent class="!w-xl !max-w-xl">
      <DialogHeader>
        <DialogTitle>История</DialogTitle>
      </DialogHeader>
      <div class="max-h-[calc(100dvh_-_10rem)] overflow-auto">
        <GameHistoryTable ref="historyTableRef" />
      </div>
      <DialogFooter class="pt-4">
        <Button type="button" variant="outline" @click="handleHistoryImageExport">
          <Icon title="icon-[tabler--photo-down]" class="size-4 text-zinc-500" />
          Сохранить изображение
        </Button>
        <Button type="button" variant="outline" @click="gameHistory.handleExportHistory">
          <Icon title="icon-[tabler--download]" class="size-4 text-zinc-500" />
          Сохранить JSON
        </Button>
        <Button type="button" variant="secondary" @click="gameHistory.handleDialogToggle(false)">
          Закрыть
        </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { ref } from 'vue'
import { Button } from '@shared/ui/button'
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@shared/ui/dialog'
import GameHistoryTable from './GameHistoryTable.vue'
import type { GameHistoryTableExpose } from './GameHistoryTable.vue'
import { useGameHistory } from './useGameHistory'

const gameHistory = useGameHistory()
const historyTableRef = ref<GameHistoryTableExpose | null>(null)

const handleHistoryImageExport = () => {
  if (!historyTableRef.value) {
    return
  }

  gameHistory.handleExportHistoryImage(historyTableRef.value.rootElement)
}
</script>
