<template>
  <Dialog :open="isRoleDialogOpen" @update:open="handleRoleDialogToggle">
    <DialogContent>
      <DialogHeader>
        <DialogTitle>{{ game.pendingRolePlayer?.name || 'Без имени' }}</DialogTitle>
        <DialogDescription>
          Этот игрок выбыл
          {{ pendingRoleReasonLabel }}. Выберите роль, чтобы завершить этап.
        </DialogDescription>
      </DialogHeader>
      <div class="flex flex-col gap-3">
        <label class="flex flex-col gap-1 text-sm text-zinc-700 dark:text-zinc-300">
          <Button
            v-for="role in ROLE_DEFINITIONS.filter((r) =>
              game.roleSummary.some((c) => c.key === r.key),
            )"
            :key="role.key"
            :value="role.key"
            :variant="roleSelection === role.key ? 'default' : 'secondary'"
            :disabled="game.roleSummary.find((item) => item.key === role.key)?.remaining === 0"
            @click="roleSelection = role.key"
          >
            {{ role.label }}
          </Button>
        </label>
      </div>
      <DialogFooter class="flex flex-col gap-2 sm:flex-row sm:justify-end">
        <Button type="button" variant="secondary" @click="handleCancelRoleAssignment">
          Отмена
        </Button>
        <Button type="button" :disabled="!roleSelection" @click="handleConfirmRoleAssignment">
          Подтвердить
        </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { useGameStore } from '@app/stores/gameStore'
import type { RoleKey } from '@processes/game-session'
import { ROLE_DEFINITIONS } from '@shared/config/roles'
import { Button } from '@shared/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@shared/ui/dialog'
import { computed, ref } from 'vue'

const game = useGameStore()

const roleSelection = ref<RoleKey | ''>('')
const isRoleDialogOpen = computed(() => Boolean(game.pendingRoleAssignment))

const pendingRoleReasonLabel = computed(() => {
  if (!game.pendingRoleAssignment) {
    return ''
  }
  return game.pendingRoleAssignment.type === 'day' ? 'днём' : 'ночью'
})

const handleRoleDialogToggle = (open: boolean) => {
  if (!open && game.pendingRoleAssignment) {
    handleCancelRoleAssignment()
  }
}

const handleCancelRoleAssignment = () => {
  roleSelection.value = ''
  game.cancelRoleAssignment()
}

const handleConfirmRoleAssignment = () => {
  if (!roleSelection.value) {
    return
  }
  game.confirmPendingRole(roleSelection.value as RoleKey)
  roleSelection.value = ''
}
</script>
