import { defineStore } from 'pinia'
import { computed, nextTick, ref, UnwrapRef, watch } from 'vue'
import { createActor } from 'xstate'

import {
  createGameSessionMachine,
  type GameSessionContext,
  type GameSessionEvent,
  type GameHistoryEntry,
  type PendingElimination,
  type PlayerSlot,
  type RoleConfig,
  type RoleKey,
  type VictoryResult,
  type VoteCandidate,
} from '@processes/game-session'
import { gameSessionStorage } from '@shared'
import type { PersistedGameSession } from '@shared'
import {
  GroupDictionary,
  ROLE_DEFINITIONS,
  ROLE_DEFINITION_MAP,
  RoleDefinition,
} from '@shared/config/roles'
import { createSnapshotHistory } from '@features/game/undo-history'
import { stageInfoMap } from './stageInfoMap'
import { RoleGroup, StageData } from '@/processes/game-session/model/types'
import { objectToFlatString } from '@/shared/lib/utils'

type StageKey = keyof typeof stageInfoMap

const stageAutoNextEventMap: Partial<Record<StageKey, GameSessionEvent>> = {
  mafiaIntroNight: { type: 'CONTINUE' },
  'mafiaIntroNight.prepare': { type: 'CONTINUE' },
  'mafiaIntroNight.meeting': { type: 'CONTINUE' },
  'mafiaIntroNight.outro': { type: 'CONTINUE' },
  'night.prepare': { type: 'CONTINUE' },
  'night.roleTurn': { type: 'COMPLETE_ROLE_TURN' },
  'night.citizen-start': { type: 'CONTINUE' },
  'night.citizen-end': { type: 'CONTINUE' },
  'night.outro': { type: 'CONTINUE' },
}

const isStageKey = (value: string): value is StageKey =>
  Object.prototype.hasOwnProperty.call(stageInfoMap, value)

const resolveAutoNextEvent = (stage: string): GameSessionEvent | null => {
  if (!isStageKey(stage)) {
    return null
  }

  const template = stageAutoNextEventMap[stage]
  if (!template) {
    return null
  }

  return { ...template }
}
// import { createBrowserInspector } from '@statelyai/inspect'

const normalizePlayers = (players: PlayerSlot[]): PlayerSlot[] =>
  players.map((player) => ({
    ...player,
    canSpeak: player.canSpeak ?? true,
    effects: Array.isArray(player.effects) ? [...player.effects] : [],
  }))

const cloneValue = <T,>(value: T): T => {
  if (typeof structuredClone === 'function') {
    return structuredClone(value)
  }

  return JSON.parse(JSON.stringify(value)) as T
}

const clonePlayers = (players: PlayerSlot[]): PlayerSlot[] =>
  players.map((player) => ({
    ...player,
    effects: Array.isArray(player.effects) ? [...player.effects] : [],
  }))

const cloneVoteCandidates = (candidates: VoteCandidate[]): VoteCandidate[] =>
  candidates.map((candidate) => ({ ...candidate }))

const clonePendingEliminations = (eliminations: PendingElimination[]): PendingElimination[] =>
  eliminations.map((elimination) => ({ ...elimination }))

const cloneNightActions = (nightActions: Record<RoleKey, string | null>) => ({
  ...nightActions,
})

const cloneDiscussionOrder = (
  discussionOrder: GameSessionContext['discussionOrder'],
): GameSessionContext['discussionOrder'] => {
  if (discussionOrder === undefined) {
    return undefined
  }

  if (discussionOrder === null) {
    return null
  }

  return { ...discussionOrder }
}

const cloneVictory = (victory: GameSessionContext['victory']): GameSessionContext['victory'] => {
  if (victory === undefined) {
    return undefined
  }

  if (victory === null) {
    return null
  }

  return { ...victory }
}

const cloneHistory = (history: GameHistoryEntry[] = []): GameHistoryEntry[] =>
  history.map((entry) => ({ ...entry }))

const cloneContext = (context: GameSessionContext): GameSessionContext => ({
  ...context,
  roleConfigs: context.roleConfigs.map((config) => ({ ...config })),
  players: clonePlayers(context.players),
  killCandidates: clonePlayers(context.killCandidates),
  votingCandidates: cloneVoteCandidates(context.votingCandidates),
  pendingEliminations: clonePendingEliminations(context.pendingEliminations),
  nightRoleOrder: [...context.nightRoleOrder],
  nightActions: cloneNightActions(context.nightActions),
  discussionOrder: cloneDiscussionOrder(context.discussionOrder),
  victory: cloneVictory(context.victory),
  monologueSpeakers: [...context.monologueSpeakers],
  history: cloneHistory(context.history),
})

const stableStringify = (value: unknown): string =>
  JSON.stringify(value, (_key, current) => (current === undefined ? '__undefined__' : current))

export const useGameStore = defineStore('game', () => {
  const machine = createGameSessionMachine()
  const persistedSession = gameSessionStorage.load()
  const hasPersistedSession = ref(Boolean(persistedSession))

  // const inspector =
  // typeof window !== 'undefined' && import.meta.env.DEV ? createBrowserInspector() : null

  const persistedSnapshot =
    persistedSession !== null
      ? machine.resolveState({
          value: persistedSession.value,
          context: {
            ...persistedSession.context,
            players: normalizePlayers(persistedSession.context.players),
          },
        })
      : undefined

  let actor = createActor(machine, {
    ...(persistedSnapshot ? { snapshot: persistedSnapshot } : {}),
    // ...(inspector ? { inspect: inspector.inspect } : {}),
  })
  actor.start()

  type ActorSnapshot = ReturnType<typeof actor.getSnapshot>
  type MachineState = ReturnType<typeof machine.resolveState>

  type GameSnapshotEntry = {
    value: MachineState['value']
    context: GameSessionContext
  }

  const areSnapshotEntriesEqual = (a: GameSnapshotEntry, b: GameSnapshotEntry) =>
    stableStringify(a.value) === stableStringify(b.value) &&
    stableStringify(a.context) === stableStringify(b.context)

  const snapshot = ref<ActorSnapshot>(actor.getSnapshot())
  const __currentState = ref<typeof snapshot.value.value>()

  const snapshotHistory = createSnapshotHistory<MachineState, GameSnapshotEntry>({
    capture: (state) => ({
      value: cloneValue(state.value),
      context: cloneContext(state.context),
    }),
    restore: (entry) =>
      machine.resolveState({
        value: cloneValue(entry.value),
        context: cloneContext(entry.context),
      }),
    areEqual: areSnapshotEntriesEqual,
  })

  snapshotHistory.bootstrap(
    machine.resolveState({ value: snapshot.value.value, context: snapshot.value.context }),
  )

  let subscription: ReturnType<typeof actor.subscribe> | null = null

  const processSnapshot = (
    nextSnapshot: ActorSnapshot,
    options: { recordHistory?: boolean; acknowledge?: boolean } = {},
  ) => {
    const { recordHistory = true, acknowledge = false } = options

    const resolvedState = machine.resolveState({
      value: nextSnapshot.value,
      context: nextSnapshot.context,
    })

    if (acknowledge) {
      snapshotHistory.acknowledge(resolvedState)
    } else if (recordHistory) {
      snapshotHistory.record(resolvedState)
    }

    snapshot.value = nextSnapshot

    const isIdle =
      nextSnapshot.matches('roleSetup') &&
      nextSnapshot.context.roleConfigs.length === 0 &&
      nextSnapshot.context.players.length === 0

    gameSessionStorage.save({
      value: nextSnapshot.value,
      context: nextSnapshot.context,
      savedAt: Date.now(),
      status: isIdle ? 'idle' : 'active',
    })

    __currentState.value = nextSnapshot.value
  }

  const subscribeToActor = () => {
    subscription?.unsubscribe()

    subscription = actor.subscribe((nextSnapshot) => {
      if (snapshotHistory.isRestoring.value) {
        processSnapshot(nextSnapshot, { recordHistory: false, acknowledge: true })
        return
      }

      processSnapshot(nextSnapshot)
    })
  }

  subscribeToActor()

  const __stateData = computed(() => JSON.stringify(snapshot.value.context, null, 2))

  const state = computed(() => snapshot.value)

  const matchesNightState = (
    substate: 'prepare' | 'roleTurn' | 'citizen-start' | 'citizen-end' | 'outro',
  ) => state.value.matches({ night: substate } as const)

  const currentStageKey = computed(() => {
    return objectToFlatString(state.value.value)
  })

  const stageInfo = computed<StageData>(
    () => stageInfoMap[currentStageKey.value] ?? stageInfoMap.roleSetup,
  )

  const getStageAutoNextEvent = () => resolveAutoNextEvent(currentStageKey.value)

  const context = computed<GameSessionContext>(() => state.value.context)
  const players = computed(() => context.value.players)
  const dayCount = computed(() => context.value.dayCount)
  const currentNightRole = computed(() => context.value.currentNightRole)
  const nightActions = computed(() => context.value.nightActions)
  const discussionOrder = computed(() => context.value.discussionOrder)
  const roleConfigs = computed(() => context.value.roleConfigs)
  const killCandidates = computed(() => context.value.killCandidates ?? [])
  const victory = computed(() => context.value.victory ?? null)
  const history = computed(() => context.value.history)

  const victoryPlayer = computed(() => {
    const result = victory.value
    if (!result || result.winner !== 'individual') {
      return null
    }

    return (
      players.value.find((player) => {
        if (!player.role) return false

        const roleDef = roleDefByKeyMap.value[player.role]
        return roleDef?.group === result.winner
      }) ?? null
    )
  })

  const victoryLabel = computed(() => {
    const result = victory.value
    if (!result) {
      return null
    }

    if (result.winner === 'individual') {
      return result.playerName ?? victoryPlayer.value?.name ?? null
    }

    return GroupDictionary[result.winner]?.title ?? null
  })

  const victoryRoleDefinition = computed(() => {
    const result = victory.value
    if (!result?.role) {
      return null
    }

    return ROLE_DEFINITIONS.find((definition) => definition.key === result.role) ?? null
  })

  const voteInputs = ref<Record<string, number>>({})

  watch(
    players,
    (list) => {
      const nextVotes: Record<string, number> = {}

      list.forEach((player) => {
        nextVotes[player.id] = voteInputs.value[player.id] ?? 0
      })

      voteInputs.value = nextVotes
    },
    { immediate: true },
  )

  const pendingEliminations = ref<string[]>([])
  const pendingRoleAssignment = ref<{
    playerId: string
    type: 'day' | 'night'
    eliminations: string[]
  } | null>(null)
  const isRoleSelectionMode = ref(false)
  const isManualVictoryDialogOpen = ref(false)

  const resetTransientUiState = () => {
    pendingEliminations.value = []
    pendingRoleAssignment.value = null
    isRoleSelectionMode.value = false
    isManualVictoryDialogOpen.value = false
  }

  watch(currentStageKey, (stage, previousStage) => {
    if (stage !== 'votingResults' && stage !== 'nightResults') {
      pendingEliminations.value = []
    }
    if (previousStage === 'votingResults' && stage !== 'votingResults') {
      voteInputs.value = {}
      submitVotes()
    }
    if (stage === 'votingResults') {
      send({
        type: 'SET_DISCUSSION_ORDER',
        firstSpeakerId: null,
        direction: discussionOrder.value?.direction ?? 'clockwise',
      })
    }
  })

  const eligibleSpeakers = computed(() =>
    players.value.filter((player) => player.isAlive && (player.canSpeak ?? true)),
  )

  const firstSpeaker = computed(() => {
    const firstSpeakerId = discussionOrder.value?.firstSpeakerId
    if (!firstSpeakerId) {
      return null
    }
    return players.value.find((player) => player.id === firstSpeakerId) ?? null
  })

  const pendingRolePlayer = computed(() => {
    const playerId = pendingRoleAssignment.value?.playerId
    if (!playerId) {
      return null
    }
    return players.value.find((player) => player.id === playerId) ?? null
  })

  const roleLabelMap = ROLE_DEFINITIONS.reduce<Record<RoleKey, string>>(
    (acc, definition) => {
      acc[definition.key] = definition.label
      return acc
    },
    {} as Record<RoleKey, string>,
  )

  const roleSummary = computed(() => {
    if (!roleConfigs.value.length) {
      return []
    }

    const eliminatedByRole = players.value.reduce<Partial<Record<RoleKey, number>>>(
      (acc, player) => {
        if (!player.isAlive && player.role) {
          acc[player.role] = (acc[player.role] ?? 0) + 1
        }
        return acc
      },
      {},
    )
    const { nightRoleOrder } = actor.getSnapshot().context
    return roleConfigs.value
      .filter((config) => config.quantity > 0)
      .map((config) => {
        const eliminated = eliminatedByRole[config.role] ?? 0
        const remaining = Math.max(0, config.quantity - eliminated)

        return {
          key: config.role,
          label: roleLabelMap[config.role] ?? config.role,
          total: config.quantity,
          eliminated,
          remaining,
        }
      })
      .sort((a, b) => nightRoleOrder.indexOf(a.key) - nightRoleOrder.indexOf(b.key))
    // .sort((a, b) => {
    //   if (b.remaining !== a.remaining) {
    //     return b.remaining - a.remaining
    //   }
    //   return a.label.localeCompare(b.label)
    // })
  })

  const roleAssignmentLimits = computed(() =>
    ROLE_DEFINITIONS.reduce<Record<RoleKey, number>>(
      (acc, definition) => {
        const configured = roleConfigs.value.find((config) => config.role === definition.key)
        acc[definition.key] = configured?.quantity ?? 0
        return acc
      },
      {} as Record<RoleKey, number>,
    ),
  )

  const assignedRoleCounts = computed(() =>
    players.value.reduce<Partial<Record<RoleKey, number>>>((acc, player) => {
      if (player.role) {
        acc[player.role] = (acc[player.role] ?? 0) + 1
      }
      return acc
    }, {}),
  )

  const roleAssignmentRemaining = computed(() => {
    const limits = roleAssignmentLimits.value
    const assigned = assignedRoleCounts.value

    return Object.entries(limits).reduce<Record<RoleKey, number>>(
      (acc, [role, limit]) => {
        const key = role as RoleKey
        const taken = assigned[key] ?? 0
        acc[key] = Math.max(0, limit - taken)
        return acc
      },
      {} as Record<RoleKey, number>,
    )
  })

  const roleAssignmentOptions = computed(() =>
    ROLE_DEFINITIONS.filter((definition) => {
      const limit = roleAssignmentLimits.value[definition.key] ?? 0
      const assigned = assignedRoleCounts.value[definition.key] ?? 0
      return limit > 0 || assigned > 0
    }),
  )

  const canUndo = snapshotHistory.canUndo
  const canRedo = snapshotHistory.canRedo

  const canContinue = computed(() => state.value.can({ type: 'CONTINUE' }))
  const canAutoAdvanceStage = computed(() => {
    const event = getStageAutoNextEvent()
    if (!event) {
      return false
    }
    return state.value.can(event)
  })
  const canRestartNight = computed(() =>
    state.value.matches('discussion')
      ? state.value.can({ type: 'RESTART_NIGHT' }) && state.value.context.dayCount === 1
      : state.value.can({ type: 'RESTART_NIGHT' }),
  )
  const canResetToDiscussion = computed(() => state.value.can({ type: 'RESET_TO_DISCUSSION' }))
  const isNightRoleTurn = computed(() => matchesNightState('roleTurn'))
  const isDiscussion = computed(() => state.value.matches('discussion'))
  const isNightResults = computed(() => state.value.matches('nightResults'))
  const isVoting = computed(() => state.value.matches('voting'))
  const isVotingResults = computed(() => state.value.matches('votingResults'))
  const isMonologues = computed(() => state.value.matches('monologues'))
  const isGameOver = computed(() => state.value.matches('gameOver'))
  const isEliminationConfirmationNeeded = computed(() =>
    Boolean(pendingEliminations.value.length && (isVotingResults.value || isNightResults.value)),
  )

  const send = (event: GameSessionEvent) => {
    actor.send(event)
  }

  const setActorState = (stateToApply: MachineState, options: { resetHistory?: boolean } = {}) => {
    const { resetHistory = false } = options

    subscription?.unsubscribe()
    subscription = null

    actor.stop()
    actor = createActor(machine, { snapshot: stateToApply })
    actor.start()
    subscribeToActor()
    resetTransientUiState()
    if (resetHistory) {
      snapshotHistory.reset(stateToApply)
    }
    processSnapshot(actor.getSnapshot(), { recordHistory: false, acknowledge: true })
  }

  const applyHistoryState = (stateToApply: MachineState) => {
    setActorState(stateToApply)
  }

  const undo = () => {
    const restoredState = snapshotHistory.undo()
    if (!restoredState) {
      return false
    }

    applyHistoryState(restoredState)
    return true
  }

  const redo = () => {
    const restoredState = snapshotHistory.redo()
    if (!restoredState) {
      return false
    }

    applyHistoryState(restoredState)
    return true
  }

  const tryAutoAdvanceStage = () => {
    const event = getStageAutoNextEvent()
    if (!event) {
      return false
    }
    if (!state.value.can(event)) {
      return false
    }

    send(event)
    return true
  }

  const initializeGame = (roleConfigs: RoleConfig[], initialPlayers: PlayerSlot[]) => {
    if (hasPersistedSession.value) {
      return
    }
    if (roleConfigs.length) {
      send({ type: 'CONFIGURE_ROLES', data: roleConfigs })
    }
    send({ type: 'START_REGISTRATION' })
    if (initialPlayers.length) {
      send({ type: 'REGISTER_PLAYERS', data: normalizePlayers(initialPlayers) })
    }
  }

  const updatePlayers = (updater: (player: PlayerSlot) => PlayerSlot) => {
    const updated = players.value.map(updater)
    send({ type: 'REGISTER_PLAYERS', data: updated })
  }

  const renamePlayer = (playerId: string, name: string) => {
    updatePlayers((player) => (player.id === playerId ? { ...player, name } : player))
  }

  const submitVotes = () => {
    const candidates: VoteCandidate[] = Object.entries(voteInputs.value)
      .filter(([, votes]) => votes > 0)
      .map(([playerId, votes]) => ({
        playerId,
        votes,
      }))

    send({ type: 'SUBMIT_VOTES', candidates })
  }

  const createSessionSnapshot = (): PersistedGameSession => ({
    value: cloneValue(state.value.value),
    context: cloneContext(state.value.context),
    savedAt: Date.now(),
    status: 'active',
  })

  const restoreFromSnapshot = (persisted: PersistedGameSession) => {
    const normalizedContext = {
      ...persisted.context,
      players: normalizePlayers(persisted.context.players ?? []),
    }

    const resolvedState = machine.resolveState({
      value: cloneValue(persisted.value),
      context: cloneContext(normalizedContext),
    })

    hasPersistedSession.value = true
    setActorState(resolvedState, { resetHistory: true })
  }

  const setVote = (playerId: string, votes: number) => {
    const normalizedVotes = Math.max(0, Number.isFinite(votes) ? votes : 0)
    const currentValue = voteInputs.value[playerId] ?? 0
    const maxAssignable = Math.max(0, currentValue + votesLeft.value)
    const clampedVotes = Math.min(normalizedVotes, maxAssignable)

    voteInputs.value = {
      ...voteInputs.value,
      [playerId]: clampedVotes,
    }

    submitVotes()
  }

  const finalizeElimination = (type: 'day' | 'night', targetIds: string[]) => {
    if (!targetIds.length) {
      return
    }

    const eliminations: PendingElimination[] = targetIds.map((playerId) => ({
      playerId,
      reason: type,
    }))

    if (type === 'day') {
      send({ type: 'CONFIRM_DAY_ELIMINATION', eliminations })
    } else {
      send({ type: 'SUBMIT_NIGHT_RESULTS', eliminations })
    }
    pendingEliminations.value = []
  }

  const ensureRolesBeforeElimination = (type: 'day' | 'night', targetIds: string[]) => {
    const playersNeedingRoles = targetIds.filter((playerId) => {
      const player = players.value.find((item) => item.id === playerId)
      return player ? !player.role : false
    })

    if (!playersNeedingRoles.length) {
      finalizeElimination(type, targetIds)
      return
    }

    pendingRoleAssignment.value = {
      playerId: playersNeedingRoles[0],
      type,
      eliminations: [...targetIds],
    }
  }

  const confirmPendingRole = (role: RoleKey) => {
    const pending = pendingRoleAssignment.value
    if (!pending) {
      return
    }

    updatePlayers((player) =>
      player.id === pending.playerId
        ? {
            ...player,
            role,
          }
        : player,
    )

    const remainingPlayers = pending.eliminations.filter((playerId) => {
      if (playerId === pending.playerId) {
        return false
      }
      const player = players.value.find((item) => item.id === playerId)
      return player ? !player.role : false
    })

    if (remainingPlayers.length) {
      pendingRoleAssignment.value = {
        playerId: remainingPlayers[0],
        type: pending.type,
        eliminations: pending.eliminations,
      }
      return
    }

    pendingRoleAssignment.value = null
    void nextTick(() => {
      finalizeElimination(pending.type, pending.eliminations)
    })
  }

  const cancelRoleAssignment = () => {
    pendingRoleAssignment.value = null
  }

  const canAssignRole = (playerId: string, role: RoleKey) => {
    const player = players.value.find((item) => item.id === playerId)
    const limit = roleAssignmentLimits.value[role] ?? 0

    if (!player) {
      return false
    }

    if (limit === 0) {
      return player.role === role
    }

    const assignedWithoutPlayer = players.value.reduce((count, current) => {
      if (current.id === playerId) {
        return count
      }
      return current.role === role ? count + 1 : count
    }, 0)

    return assignedWithoutPlayer < limit
  }

  const assignRoleToPlayer = (playerId: string, role: RoleKey | null) => {
    const player = players.value.find((item) => item.id === playerId)

    if (!player) {
      return
    }

    if (role && !canAssignRole(playerId, role)) {
      return
    }

    updatePlayers((item) =>
      item.id === playerId
        ? {
            ...item,
            role,
          }
        : item,
    )
  }

  const toggleElimination = (playerId: string, type: 'day' | 'night') => {
    if (pendingEliminations.value.includes(playerId)) {
      pendingEliminations.value = pendingEliminations.value.filter((id) => id !== playerId)
    } else {
      pendingEliminations.value = [...pendingEliminations.value, playerId]
    }
  }

  const confirmDayEliminations = () => {
    const targetIds = [...pendingEliminations.value]
    if (!targetIds.length) {
      return
    }

    ensureRolesBeforeElimination('day', targetIds)
  }

  const confirmNightEliminations = () => {
    const targetIds = [...pendingEliminations.value]
    if (!targetIds.length) {
      return
    }

    ensureRolesBeforeElimination('night', targetIds)
  }

  const togglePlayerCanSpeak = (playerId: string, value: boolean) => {
    updatePlayers((player) => (player.id === playerId ? { ...player, canSpeak: value } : player))
  }

  const togglePlayerGoldenMinute = (playerId: string, value: boolean) => {
    updatePlayers((player) =>
      player.id === playerId ? { ...player, haveGoldenMinute: value } : player,
    )
  }

  const chooseRandomSpeaker = () => {
    const candidates = eligibleSpeakers.value
    if (!candidates.length) {
      return
    }
    const selected = candidates[Math.floor(Math.random() * candidates.length)] ?? candidates[0]
    const direction = discussionOrder.value?.direction ?? 'clockwise'

    send({
      type: 'SET_DISCUSSION_ORDER',
      firstSpeakerId: selected.id,
      direction,
    })
  }

  const selectNightTarget = (targetId: string | null) => {
    const role = currentNightRole.value
    if (!role) {
      return
    }

    send({ type: 'SET_NIGHT_CHOICE', role, targetId })
  }

  const completeNightRole = () => {
    send({ type: 'COMPLETE_ROLE_TURN' })
  }

  const continueStage = () => {
    send({ type: 'CONTINUE' })
  }

  const restartNight = () => {
    send({ type: 'RESTART_NIGHT' })
  }

  const returnToMonologues = () => {
    send({ type: 'RETURN_TO_MONOLOGUES' })
  }

  const resetToDiscussion = () => {
    send({ type: 'RESET_TO_DISCUSSION' })
  }

  const finishGame = (result?: VictoryResult | null) => {
    isManualVictoryDialogOpen.value = false
    send({ type: 'FINISH_GAME', result })
  }

  const resetGame = () => {
    gameSessionStorage.clear()
    voteInputs.value = {}
    pendingEliminations.value = []
    isManualVictoryDialogOpen.value = false
    send({ type: 'RESET_GAME' })
    hasPersistedSession.value = false
  }

  const openRoleSelection = () => {
    isRoleSelectionMode.value = true
  }

  const closeRoleSelection = () => {
    isRoleSelectionMode.value = false
  }

  const openManualVictoryDialog = () => {
    isManualVictoryDialogOpen.value = true
  }

  const closeManualVictoryDialog = () => {
    isManualVictoryDialogOpen.value = false
  }

  const isLightOff = computed(
    () => state.value.matches('night') || state.value.matches('mafiaIntroNight'),
  )

  const totalVotes = computed(() => players.value.filter((p) => p.isAlive).length)
  const votesLeft = computed(() => {
    const usedVotes = Object.values(voteInputs.value).reduce((sum, v) => sum + v, 0)
    return Math.max(0, totalVotes.value - usedVotes)
  })

  const alivePlayers = computed(() => players.value.filter((p) => p.isAlive))
  const deadPlayers = computed(() => players.value.filter((p) => !p.isAlive))
  const aliveCount = computed(() => alivePlayers.value.length)
  const deadCount = computed(() => deadPlayers.value.length)

  const nextButtonText = computed(() => {
    return (
      {
        roleSetup: 'Начать регистрацию', // "Start Registration"
        playerRegistration: 'К ночи знакомства мафии', // "Start Game"
        mafiaIntroNight: 'К первому дню', // "Proceed to Day"
        'mafiaIntroNight.prepare': 'К первому дню', // "Proceed to Day"
        'mafiaIntroNight.meeting': 'К первому дню', // "Proceed to Day"
        'mafiaIntroNight.outro': 'К первому дню', // "Proceed to Day"
        discussion: 'К монологам', // "Proceed to Monologues"
        monologues: 'К голосованию', // "Proceed to Voting"
        voting: 'Завершить голосование', // "Complete Voting"
        votingResults: 'К ночи',
        'night.prepare': 'Начать ночь', // "Start Night"
        'night.roleTurn': 'Завершить ход роли', // "Complete Role Turn"
        'night.citizen-start': 'Начать блок горожан',
        'night.citizen-end': 'Завершить блок горожан',
        'night.outro': 'Завершить ночь',
        night: 'Завершить ночь',
        nightResults: 'Ко дню',
      } as Partial<Record<UnwrapRef<typeof currentStageKey>, string>>
    )[currentStageKey.value]
  })

  const currentRoleDefinition = computed(() =>
    ROLE_DEFINITIONS.find((definition) => definition.key === currentNightRole.value),
  )

  const currentAudioTitle = computed(() => {
    const audioTitle = currentRoleDefinition.value?.audio || stageInfo.value.audio || null
    if (isStressMode.value && audioTitle === 'day.mp3') {
      return 'day-stress.mp3'
    }
    return audioTitle
  })

  const aliveCountByTeam = computed(() => {
    const counts = alivePlayers.value.reduce(
      (acc, player) => {
        const roleKey = player.role
        const team = roleKey ? (ROLE_DEFINITION_MAP[roleKey]?.group ?? 'unknown') : 'unknown'
        acc[team] = (acc[team] ?? 0) + 1
        return acc
      },
      {} as Record<RoleGroup | 'unknown', number>,
    )

    players.value.forEach((player) => {
      if (!player.role) {
        return
      }

      const team = ROLE_DEFINITION_MAP[player.role]?.group ?? 'unknown'
      if (!(team in counts)) {
        counts[team] = 0
      }
    })

    return counts
  })

  const isStressMode = ref(false)
  const isHistoryDialogOpen = ref(false)

  const playerByRoleMap = computed(() =>
    roleConfigs.value.reduce(
      (acc, roleConfig) => {
        const playerList = players.value.filter((player) => player.role === roleConfig.role)
        if (playerList.length) {
          acc[roleConfig.role] = playerList
        }
        return acc
      },
      {} as Record<RoleKey, PlayerSlot[]>,
    ),
  )

  const roleKeyByPlayerIdMap = computed(() =>
    players.value.reduce(
      (acc, player) => {
        acc[player.id] = player.role

        return acc
      },
      {} as Record<string, RoleKey | null>,
    ),
  )

  const roleDefByKeyMap = computed(() =>
    ROLE_DEFINITIONS.reduce(
      (acc, def) => {
        acc[def.key] = def
        return acc
      },
      {} as Record<RoleKey, RoleDefinition>,
    ),
  )

  const isInSensitiveMode = ref(false)
  const setIsInSensitiveMode = (value: boolean) => {
    isInSensitiveMode.value = value
  }

  return {
    stageInfo,
    currentStageKey,
    players,
    dayCount,
    currentNightRole,
    nightActions,
    killCandidates,
    victory,
    victoryLabel,
    victoryPlayer,
    victoryRoleDefinition,
    roleSummary,
    roleConfigs,
    history,
    voteInputs,
    pendingEliminations,
    pendingRoleAssignment,
    eligibleSpeakers,
    firstSpeaker,
    pendingRolePlayer,
    canContinue,
    canAutoAdvanceStage,
    canUndo,
    canRedo,
    canRestartNight,
    canResetToDiscussion,
    isNightRoleTurn,
    isNightResults,
    isDiscussion,
    isVoting,
    isVotingResults,
    isMonologues,
    isGameOver,
    undo,
    redo,
    initializeGame,
    setVote,
    toggleElimination,
    confirmDayEliminations,
    confirmNightEliminations,
    confirmPendingRole,
    cancelRoleAssignment,
    assignRoleToPlayer,
    canAssignRole,
    togglePlayerCanSpeak,
    togglePlayerGoldenMinute,
    renamePlayer,
    chooseRandomSpeaker,
    selectNightTarget,
    completeNightRole,
    tryAutoAdvanceStage,
    continueStage,
    restartNight,
    returnToMonologues,
    resetToDiscussion,
    finishGame,
    resetGame,
    createSessionSnapshot,
    restoreFromSnapshot,
    hasPersistedSession,
    isLightOff,
    totalVotes,
    votesLeft,
    isEliminationConfirmationNeeded,
    alivePlayers,
    deadPlayers,
    aliveCount,
    deadCount,
    nextButtonText,
    currentRoleDefinition,
    currentAudioTitle,
    isRoleSelectionMode,
    openRoleSelection,
    closeRoleSelection,
    isManualVictoryDialogOpen,
    openManualVictoryDialog,
    closeManualVictoryDialog,
    roleAssignmentOptions,
    roleAssignmentRemaining,
    roleAssignmentLimits,
    __stateData,
    __currentState,
    aliveCountByTeam,
    isStressMode,
    isHistoryDialogOpen,
    playerByRoleMap,
    roleKeyByPlayerIdMap,
    roleDefByKeyMap,
    isInSensitiveMode,
    setIsInSensitiveMode,
  }
})
