<template>
  <div class="dark relative h-dvh overflow-auto bg-zinc-900">
    <ul class="grid grid-cols-1 dark:text-white">
      <li v-for="player in game.players" :key="player.id" class="border-b border-b-zinc-500">
        <div
          class="grid h-full w-full grid-cols-3 justify-center py-4 items-baseline"
          role="button"
          @click="setSelected(player)"
        >
          <div />
          <div class="text-center">
            {{ player.name }}
          </div>
          <div>
            <span
              class="flex justify-end pr-5 text-end text-xs whitespace-nowrap text-zinc-700 transition-opacity"
              >{{ player.role ? game.roleDefByKeyMap[player.role].label : 'х/з' }}</span
            >
          </div>
        </div>
      </li>
    </ul>

    <div class="absolute bottom-0 left-0 flex w-full justify-around gap-2 pb-8 pt-4">
      <Button class="rounded-3xl h-16 flex-1 bg-red-800" @click="setPersonBadBannerOpened(true)">😈</Button>
      <Button class="rounded-3xl h-16 flex-1 bg-green-600" @click="setPersonGoodBannerOpened(true)">😇</Button>
    </div>
    <Dialog :open="!!selected" @update:open="handleOpenUpdate">
      <DialogContent v-if="selected" class="dark h-dvh text-white">
        <div
          ref="nameContainer"
          class="flex size-full items-center justify-center"
          :style="nameStyles"
        >
          {{ selected.name }}?
        </div>
      </DialogContent>
    </Dialog>

    <Dialog :open="!!selected" @update:open="handleOpenUpdate">
      <DialogContent v-if="selected" class="dark h-dvh text-white">
        <div
          ref="nameContainer"
          class="flex size-full items-center justify-center"
          :style="nameStyles"
        >
          {{ selected.name }}?
        </div>
      </DialogContent>
    </Dialog>

    <Dialog
      :open="!!isPersonGoodBannerOpened"
      @update:open="
        (value) => {
          if (!value) {
            setPersonGoodBannerOpened(false)
          }
        }
      "
    >
      <DialogContent class="dark h-dvh text-white">
        <div
          class="flex size-full flex-col-reverse items-center justify-center bg-green-700 text-8xl"
          style="writing-mode: vertical-lr"
        >
          <div class="rotate-90">😇</div>
          <div>За горожан</div>
        </div>
      </DialogContent>
    </Dialog>

    <Dialog
      :open="!!isPersonBadBannerOpened"
      @update:open="
        (value) => {
          if (!value) {
            setPersonBadBannerOpened(false)
          }
        }
      "
    >
      <DialogContent class="dark h-dvh text-white">
        <div
          class="flex size-full flex-col-reverse items-center justify-center bg-red-800 text-8xl"
          style="writing-mode: vertical-lr"
        >
          <div class="rotate-90">😈</div>
          <div>Преступник!</div>
        </div>
      </DialogContent>
    </Dialog>
  </div>
</template>

<script setup lang="ts">
import { useGameStore } from '@/app/stores/gameStore'
import type { PlayerSlot } from '@/processes/game-session'
import { useResizeObserver } from '@vueuse/core'
import { computed, ref, type CSSProperties } from 'vue'

const game = useGameStore()
const selected = ref<PlayerSlot | null>(null)
const setSelected = (player: PlayerSlot | null) => {
  selected.value = player
}
const handleOpenUpdate = (open: boolean) => {
  if (!open) {
    setSelected(null)
  }
}

const nameContainer = ref<HTMLElement | null>(null)
const containerHeight = ref(0)

const isPersonGoodBannerOpened = ref(false)
const isPersonBadBannerOpened = ref(false)

const setPersonGoodBannerOpened = (value: boolean) => {
  isPersonGoodBannerOpened.value = value
}
const setPersonBadBannerOpened = (value: boolean) => {
  isPersonBadBannerOpened.value = value
}
useResizeObserver(nameContainer, (entries) => {
  const entry = entries[0]
  if (entry) {
    containerHeight.value = entry.contentRect.height
  }
})

const nameLength = computed(() => {
  const raw = selected.value?.name ?? ''
  const normalized = raw.replace(/\s+/gu, '')
  const effectiveLength = normalized.length + 1 // account for question mark
  return effectiveLength || 1
})

const fontSizePx = computed(() => {
  if (!containerHeight.value) {
    return 0
  }
  const rawSize = (containerHeight.value / nameLength.value) * 1.5
  const clamped = Math.max(Math.min(rawSize, containerHeight.value), 16)
  return clamped
})

const nameStyles = computed<CSSProperties>(() => {
  const styles: CSSProperties = {
    writingMode: 'vertical-rl',
    lineHeight: '1',
  }

  if (fontSizePx.value) {
    styles.fontSize = `${fontSizePx.value}px`
  }

  return styles
})
</script>
