import type {
  GameHistoryEntry,
  GameSessionContext,
  RoleKey,
  VoteCandidate,
} from '@processes/game-session'
import { DEFAULT_NIGHT_ROLE_ORDER } from '@processes/game-session'
import { ROLE_DEFINITIONS } from '@shared/config/roles'
import type { StateValue } from 'xstate'

const STORAGE_KEY = 'mafia-standalone/game-session'

export type PersistedGameSessionStatus = 'idle' | 'active'

export interface PersistedGameSession {
  value: StateValue
  context: GameSessionContext
  savedAt: number
  status?: PersistedGameSessionStatus
}

const isBrowser = typeof window !== 'undefined' && typeof window.localStorage !== 'undefined'

const isRoleSetupState = (value: StateValue): boolean => {
  if (typeof value === 'string') {
    return value === 'roleSetup'
  }

  if (value && typeof value === 'object') {
    return Object.prototype.hasOwnProperty.call(value, 'roleSetup')
  }

  return false
}

const isContextEmpty = (context: GameSessionContext): boolean => {
  const hasRoles = Array.isArray(context.roleConfigs) && context.roleConfigs.length > 0
  const hasPlayers = Array.isArray(context.players) && context.players.length > 0

  return !hasRoles && !hasPlayers
}

const resolveSnapshotStatus = (
  snapshot: Pick<PersistedGameSession, 'status' | 'value' | 'context'>,
): PersistedGameSessionStatus => {
  if (snapshot.status === 'idle' || snapshot.status === 'active') {
    return snapshot.status
  }

  if (isRoleSetupState(snapshot.value) && isContextEmpty(snapshot.context)) {
    return 'idle'
  }

  return 'active'
}

export const gameSessionStorage = {
  save(snapshot: PersistedGameSession) {
    if (!isBrowser) {
      return
    }
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(snapshot))
  },
  load(): PersistedGameSession | null {
    if (!isBrowser) {
      return null
    }
    const raw = window.localStorage.getItem(STORAGE_KEY)
    if (!raw) {
      return null
    }
    try {
      const parsed = JSON.parse(raw) as PersistedGameSession
      if (parsed && typeof parsed === 'object' && 'value' in parsed && 'context' in parsed) {
        const normalizedNightRoleOrder = normalizeNightRoleOrder(parsed.context.nightRoleOrder)
        const normalizedNightActions = normalizeNightActions(parsed.context.nightActions)
        const normalizedNightRoleIndex = normalizeNightRoleIndex(
          parsed.context.nightRoleIndex,
          normalizedNightRoleOrder.length,
        )
        const normalizedCurrentNightRole =
          normalizedNightRoleIndex >= 0
            ? normalizedNightRoleOrder[normalizedNightRoleIndex]
            : undefined

        const normalizedSnapshot: PersistedGameSession = {
          ...parsed,
          context: {
            ...parsed.context,
            nightRoleOrder: normalizedNightRoleOrder,
            nightActions: normalizedNightActions,
            nightRoleIndex: normalizedNightRoleIndex,
            currentNightRole: normalizedCurrentNightRole,
            votingCandidates: normalizeVotingCandidates(parsed.context.votingCandidates),
            monologueSpeakers: normalizeMonologueSpeakers(parsed.context.monologueSpeakers),
            history: normalizeHistory(parsed.context.history),
            players: Array.isArray(parsed.context.players)
              ? parsed.context.players.map((player) => ({
                  ...player,
                  isAlive: player.isAlive ?? (player as { alive?: boolean }).alive ?? true,
                  canSpeak: player.canSpeak ?? true,
                  haveGoldenMinute: player.haveGoldenMinute ?? true,
                  effects: Array.isArray(player.effects) ? [...player.effects] : [],
                }))
              : [],
          },
        }

        const status = resolveSnapshotStatus(normalizedSnapshot)
        if (status === 'idle') {
          return null
        }

        return {
          ...normalizedSnapshot,
          status,
        }
      }
    } catch {
      window.localStorage.removeItem(STORAGE_KEY)
    }
    return null
  },
  clear() {
    if (!isBrowser) {
      return
    }
    window.localStorage.removeItem(STORAGE_KEY)
  },
}

const normalizeNightActions = (
  nightActions: GameSessionContext['nightActions'] | undefined,
): GameSessionContext['nightActions'] => {
  const knownRoles = ROLE_DEFINITIONS.map((definition) => definition.key)

  return knownRoles.reduce<GameSessionContext['nightActions']>(
    (acc, role) => {
      acc[role] = nightActions?.[role] ?? null
      return acc
    },
    {} as GameSessionContext['nightActions'],
  )
}

const normalizeNightRoleOrder = (nightRoleOrder: RoleKey[] | undefined): RoleKey[] => {
  const knownRoles = ROLE_DEFINITIONS.map((definition) => definition.key)
  const defaults = DEFAULT_NIGHT_ROLE_ORDER.filter((role) => knownRoles.includes(role))

  if (!Array.isArray(nightRoleOrder)) {
    return defaults
  }

  const seen = new Set<RoleKey>()
  const result: RoleKey[] = []

  nightRoleOrder.forEach((role) => {
    if (knownRoles.includes(role) && !seen.has(role)) {
      seen.add(role)
      result.push(role)
    }
  })

  if (!result.length) {
    return defaults
  }

  return result
}

const normalizeNightRoleIndex = (index: number | undefined, orderLength: number): number => {
  if (typeof index !== 'number' || !Number.isFinite(index)) {
    return -1
  }

  if (orderLength === 0) {
    return -1
  }

  return Math.min(Math.max(index, -1), orderLength - 1)
}

const normalizeVotingCandidates = (
  votingCandidates: GameSessionContext['votingCandidates'] | undefined,
): GameSessionContext['votingCandidates'] => {
  if (!Array.isArray(votingCandidates)) {
    return []
  }

  return votingCandidates
    .map((candidate) => {
      if (!candidate || typeof candidate !== 'object') {
        return null
      }
      const { playerId, votes } = candidate as Partial<VoteCandidate>
      if (typeof playerId !== 'string') {
        return null
      }
      const normalizedVotes = typeof votes === 'number' && Number.isFinite(votes) ? votes : 0
      return { playerId, votes: normalizedVotes }
    })
    .filter((candidate): candidate is VoteCandidate => candidate !== null)
}

const normalizeMonologueSpeakers = (
  monologueSpeakers: GameSessionContext['monologueSpeakers'] | undefined,
): GameSessionContext['monologueSpeakers'] => {
  if (!Array.isArray(monologueSpeakers)) {
    return []
  }

  return monologueSpeakers.filter((id): id is string => typeof id === 'string')
}

const normalizeHistory = (
  history: GameSessionContext['history'] | undefined,
): GameHistoryEntry[] => {
  if (!Array.isArray(history)) {
    return []
  }

  const allowedGroups: Array<GameHistoryEntry['group']> = ['mafia', 'city', 'individual']
  const allowedPhases: Array<GameHistoryEntry['phase']> = ['day', 'night']
  const allowedActions: Array<GameHistoryEntry['action']> = [
    'shotted',
    'healed',
    'checked',
    'blocked',
    'habilitated',
    'eliminated',
  ]

  return history
    .map((entry) => {
      if (!entry || typeof entry !== 'object') {
        return null
      }

      const {
        id,
        day,
        dayCount,
        phase,
        role,
        group,
        effectQuality,
        action,
        targetId,
        timestamp,
        isFatal,
      } = entry as Partial<GameHistoryEntry> & { dayCount?: number }

      if (typeof id !== 'string' || !id) {
        return null
      }

      if (typeof day !== 'number' || !Number.isFinite(day)) {
        return null
      }

      if (!allowedPhases.includes(phase as GameHistoryEntry['phase'])) {
        return null
      }

      if (role !== null && typeof role !== 'string') {
        return null
      }

      if (!allowedGroups.includes(group as GameHistoryEntry['group'])) {
        return null
      }

      if (!allowedActions.includes(action as GameHistoryEntry['action'])) {
        return null
      }

      if (targetId !== null && typeof targetId !== 'string') {
        return null
      }

      if (typeof timestamp !== 'number' || !Number.isFinite(timestamp)) {
        return null
      }

      if (typeof isFatal !== 'boolean') {
        return null
      }

      const normalizedDayCount =
        typeof dayCount === 'number' && Number.isFinite(dayCount) ? dayCount : day

      return {
        id,
        day,
        dayCount: normalizedDayCount,
        phase: phase as GameHistoryEntry['phase'],
        role: role as GameHistoryEntry['role'],
        group: group as GameHistoryEntry['group'],
        action: action as GameHistoryEntry['action'],
        effectQuality: effectQuality as GameHistoryEntry['effectQuality'] || null,
        targetId: targetId ?? null,
        timestamp,
        isFatal,
      }
    })
    .filter((entry): entry is GameHistoryEntry => entry !== null)
}
