<template>
  <Dialog :open="isOpen" @update:open="handleDialogToggle">
    <DialogContent class="max-w-xl">
      <DialogHeader>
        <DialogTitle>Назначение ролей</DialogTitle>
      </DialogHeader>
      <div class="grid max-h-[60vh] grid-cols-2 flex-col gap-3 overflow-y-auto pr-1">
        <div v-for="player in orderedPlayers" :key="player.id" class="contents">
          <div class="flex items-center justify-between">
            <span class="text-sm font-medium text-zinc-700 dark:text-white">
              {{ player.name || 'Без имени' }}
            </span>
          </div>
          <Select
            :model-value="resolveSelectValue(player)"
            @update:model-value="(value) => handleRoleSelect(player.id, value)"
          >
            <SelectTrigger
              class="w-full justify-between border border-zinc-200 bg-white text-left text-sm dark:border-zinc-600 dark:bg-zinc-700 dark:text-white"
              :class="!player.role && 'text-zinc-400'"
            >
              <SelectValue placeholder="Выберите роль" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem :value="ROLE_NONE_VALUE">
                <span class="text-zinc-500"> — Не указано — </span>
              </SelectItem>
              <SelectItem
                v-for="role in roleAssignmentOptions"
                :key="role.key"
                :value="role.key"
                :disabled="isRoleOptionDisabled(player.id, role.key)"
              >
                {{ role.label }}
              </SelectItem>
            </SelectContent>
          </Select>
        </div>
        <p v-if="!orderedPlayers.length" class="text-sm text-zinc-500 dark:text-zinc-400">
          Игроки ещё не добавлены.
        </p>
      </div>
      <DialogFooter class="mt-2 flex flex-col gap-2 sm:flex-row sm:justify-end">
        <Button type="button" variant="secondary" @click="handleClose">Закрыть</Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { useGameStore } from '@app/stores/gameStore'
import type { RoleKey } from '@processes/game-session'
import { Button } from '@shared/ui/button'
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@shared/ui/dialog'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@shared/ui/select'
import { storeToRefs } from 'pinia'
import { AcceptableValue } from 'reka-ui'
import { computed } from 'vue'

const ROLE_NONE_VALUE = '__none__'

const game = useGameStore()
const { players, roleAssignmentOptions, isRoleSelectionMode } = storeToRefs(game)

const orderedPlayers = computed(() =>
  [...players.value].sort((a, b) => Number(b.isAlive) - Number(a.isAlive)),
)

const isOpen = computed(() => isRoleSelectionMode.value)

const resolveSelectValue = (player: (typeof players.value)[number]) =>
  player.role ?? ROLE_NONE_VALUE

const handleRoleSelect = (playerId: string, value: AcceptableValue) => {
  if (value === ROLE_NONE_VALUE) {
    game.assignRoleToPlayer(playerId, null)
    return
  }

  game.assignRoleToPlayer(playerId, value as RoleKey)
}

const isRoleOptionDisabled = (playerId: string, roleKey: RoleKey) =>
  !game.canAssignRole(playerId, roleKey)

const handleClose = () => {
  game.closeRoleSelection()
}

const handleDialogToggle = (open: boolean) => {
  if (!open) {
    handleClose()
  }
}
</script>
