import { nextTick, reactive, watch } from 'vue'
import type { Ref } from 'vue'
import type { PlayerSlot } from '@processes/game-session'

type UsePlayerEditingOptions = {
  players: Ref<PlayerSlot[]>
  currentStageKey: Ref<string>
  isRoleSelectionMode: Ref<boolean>
  focusContainer: Ref<HTMLElement | null>
  renamePlayer: (playerId: string, name: string) => void
}

const isPlayerNameEmpty = (player: PlayerSlot) => !player.name || player.name.trim().length === 0

export const usePlayerEditing = ({
  players,
  currentStageKey,
  isRoleSelectionMode,
  focusContainer,
  renamePlayer,
}: UsePlayerEditingOptions) => {
  const manualEditingStates = reactive<Record<string, boolean>>({})

  const cancelEdit = (player?: PlayerSlot) => {
    if (player) {
      manualEditingStates[player.id] = false
      return
    }

    Object.keys(manualEditingStates).forEach((playerId) => {
      manualEditingStates[playerId] = false
    })
  }

  const startEdit = (player: PlayerSlot) => {
    manualEditingStates[player.id] = true
  }

  const commitEdit = (player: PlayerSlot, name: string) => {
    renamePlayer(player.id, name)
    manualEditingStates[player.id] = !name.length

    nextTick(() => {
      focusContainer.value?.querySelector<HTMLInputElement>('input')?.focus()
    })
  }

  const isEditingPlayer = (player: PlayerSlot) =>
    currentStageKey.value === 'playerRegistration' &&
    (isPlayerNameEmpty(player) || Boolean(manualEditingStates[player.id]))

  watch(
    [players, currentStageKey],
    ([list, stage]) => {
      const ids = new Set(list.map((player) => player.id))
      const inRegistration = stage === 'playerRegistration'

      list.forEach((player) => {
        if (manualEditingStates[player.id] === undefined) {
          manualEditingStates[player.id] = inRegistration && isPlayerNameEmpty(player)
          return
        }

        if (inRegistration && isPlayerNameEmpty(player)) {
          manualEditingStates[player.id] = true
        }

        if (!inRegistration) {
          manualEditingStates[player.id] = false
        }
      })

      Object.keys(manualEditingStates).forEach((playerId) => {
        if (!ids.has(playerId)) {
          delete manualEditingStates[playerId]
        }
      })
    },
    { immediate: true },
  )

  watch(isRoleSelectionMode, (active) => {
    if (active) {
      cancelEdit()
    }
  })

  watch(currentStageKey, (nextStage) => {
    if (nextStage !== 'playerRegistration') {
      cancelEdit()
    }
  })

  return {
    startEdit,
    cancelEdit,
    commitEdit,
    isEditingPlayer,
  }
}
