<template>
  <section class="relative flex h-full flex-col items-center justify-center gap-8 py-8 text-center">
    <header class="space-y-3">
      <p class="text-sm font-semibold tracking-wide text-zinc-500 uppercase">Игра завершена</p>
      <h1 class="text-3xl font-bold dark:text-green-400">
        {{ title }}
      </h1>
      <p v-if="description" class="text-lg text-zinc-600 dark:text-zinc-300">
        {{ description }}
      </p>
    </header>
    <div class="grid-rows-auto grid w-full max-w-md grid-cols-1 gap-4">
      <div class="absolute bottom-0 left-0 flex w-full justify-center py-8">
        <AudioPlayer
          v-if="victoryAudioSrc"
          :src="victoryAudioSrc"
          :autoplay="true"
          class="w-full max-w-md"
        />
      </div>
      <Button class="w-full max-w-md" @click="handleShowHistory">
        <Icon title="icon-[tabler--history]" class="size-4" />
        Посмотреть историю</Button
      >
      <Button type="button" variant="outline" @click="handleRestart"
        >Новая партия
        <Icon title="icon-[tabler--player-play-filled]" class="size-4" />
      </Button>
    </div>
  </section>
  <GameHistoryDialog />
</template>

<script setup lang="ts">
import { GameHistoryDialog } from '@/features/game/show-game-history'
import { computed } from 'vue'

import type { VictoryResult } from '@processes/game-session'
import { GroupDictionary, ROLE_DEFINITIONS } from '@shared/config/roles'
import { Button } from '@shared/ui/button'
import { useGameStore } from '@/app/stores/gameStore'
import { resolveInternalLink } from '@/shared/lib/utils'

const props = defineProps<{
  victory: VictoryResult | null
}>()

const emit = defineEmits<{
  restart: []
  reset: []
}>()

const game = useGameStore()
const roleDefinition = computed(() => {
  if (!props.victory?.role) {
    return null
  }

  return ROLE_DEFINITIONS.find((definition) => definition.key === props.victory?.role) ?? null
})

const title = computed(() => {
  const result = props.victory
  if (!result) {
    return 'Игра завершена'
  }

  // if (result.winner === 'individual') {
  //   return `Победили ${result.playerName ?? 'неизвестного игрока'}`
  // }

  const group = GroupDictionary[result.winner]

  return group ? `Победили ${group.title.toLowerCase()}` : 'Игра завершена'
})

const description = computed(() => {
  const result = props.victory
  if (!result) {
    return 'Фиксируйте результат партии и при необходимости начните новую игру.'
  }

  if (result.winner === 'individual') {
    const name = result.playerName ?? 'Неизвестный игрок'
    const roleLabel = roleDefinition.value?.label

    return roleLabel
      ? `${name} (${roleLabel}) остался единственным игроком в городе.`
      : `${name} остался единственным игроком в городе.`
  }

  const group = GroupDictionary[result.winner]

  return group ? `${group.title} сохранили контроль над городом.` : null
})

const victoryAudioSrc = computed(() => {
  const result = props.victory
  if (!result) {
    return null
  }

  switch (result.winner) {
    case 'city':
      return resolveInternalLink('/audio/won-citizen.mp3')
    case 'mafia':
      return resolveInternalLink('/audio/won-mafia.mp3')
    case 'individual':
      return resolveInternalLink('/audio/won-individual.mp3')
    default:
      return null
  }
})

const handleRestart = () => {
  emit('restart')
}

const handleReset = () => {
  emit('reset')
}

const handleShowHistory = () => {
  game.isHistoryDialogOpen = true
}
</script>
