<template>
  <div
    :class="
      cn(
        'border-input flex overflow-hidden rounded-md border px-0 text-center text-sm shadow-xs',
        props.class,
      )
    "
  >
    <button
      type="button"
      class="flex w-6 cursor-pointer items-center justify-center border-r border-zinc-500/5 bg-zinc-300/30 text-center transition disabled:opacity-20"
      tabindex="-1"
      :disabled="isAtMin"
      @click="handleDecrease"
    >
      -
    </button>
    <input
      v-model="modelValue"
      data-slot="input"
      type="number"
      :min="minValue"
      :max="maxAttribute"
      step="1"
      pattern="\d*"
      inputmode="numeric"
      autocomplete="off"
      spellcheck="false"
      aria-label="Number input"
      :class="[
        'file:text-foreground placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground dark:bg-input/30 border-input flex w-20 max-w-6 min-w-0 appearance-none items-center justify-center bg-transparent px-0 py-1 text-center text-base transition-[color,box-shadow] outline-none file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm',
        'focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px]',
        'aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive',
      ]"
    />
    <button
      type="button"
      class="flex w-6 cursor-pointer items-center justify-center border-l border-zinc-500/5 bg-zinc-300/30 text-center transition disabled:opacity-20"
      tabindex="-1"
      :disabled="isAtMax || isMaxDisabled"
      @click="handleIncrease"
    >
      +
    </button>
  </div>
</template>

<script setup lang="ts">
import type { HTMLAttributes } from 'vue'
import { computed, watch } from 'vue'
import { useVModel } from '@vueuse/core'
import { cn } from '@/shared/lib/utils'

const props = defineProps<{
  defaultValue?: string | number
  modelValue?: string | number
  class?: HTMLAttributes['class']
  min?: number
  max?: number
  isMaxDisabled?: boolean
}>()

const emits = defineEmits<{
  (e: 'update:modelValue', payload: string | number): void
}>()

const modelValue = useVModel(props, 'modelValue', emits, {
  passive: true,
  defaultValue: props.defaultValue,
})

const minValue = computed(() => {
  const numericMin = Number(props.min ?? 0)
  return Number.isNaN(numericMin) ? 0 : numericMin
})

const maxValue = computed(() => {
  if (props.max === undefined || props.max === null) {
    return Number.POSITIVE_INFINITY
  }
  const numericMax = Number(props.max)
  return Number.isNaN(numericMax) ? Number.POSITIVE_INFINITY : numericMax
})

const maxAttribute = computed(() => (Number.isFinite(maxValue.value) ? maxValue.value : undefined))

const numericValue = computed(() => {
  const value = Number(modelValue.value)
  if (Number.isNaN(value)) {
    return minValue.value
  }
  return value
})

const isAtMin = computed(() => numericValue.value <= minValue.value)
const isAtMax = computed(() => numericValue.value >= maxValue.value)

const clamp = (value: number) => {
  return Math.min(Math.max(value, minValue.value), maxValue.value)
}

const emitClamped = (value: number) => {
  const clampedValue = clamp(value)
  emits('update:modelValue', clampedValue)
}

const handleDecrease = () => {
  emitClamped(numericValue.value - 1)
}

const handleIncrease = () => {
  emitClamped(numericValue.value + 1)
}

watch(
  () => [modelValue.value, minValue.value, maxValue.value],
  ([rawValue]) => {
    const numeric = Number(rawValue)
    if (Number.isNaN(numeric)) {
      return
    }
    const clampedValue = clamp(numeric)
    if (clampedValue !== numeric) {
      emitClamped(clampedValue)
    }
  },
)
</script>

<style scoped>
input::-webkit-outer-spin-button,
input::-webkit-inner-spin-button {
  /* display: none; <- Crashes Chrome on hover */
  -webkit-appearance: none;
  margin: 0; /* <-- Apparently some margin are still there even though it's hidden */
}

input[type='number'] {
  -moz-appearance: textfield; /* Firefox */
}
</style>
