<template>
  <Dialog :open="isOpen" @update:open="handleDialogToggle">
    <DialogContent class="sm:max-w-md">
      <DialogHeader>
        <DialogTitle>Выбор победителя</DialogTitle>
        <DialogDescription>
          Завершите игру вручную: выберите команду, которой присуждается победа.
        </DialogDescription>
      </DialogHeader>
      <div class="space-y-4">
        <div
          class="rounded-md border border-zinc-200 bg-zinc-50 p-3 text-sm dark:border-zinc-700 dark:bg-zinc-900/40"
        >
          <p class="mb-2 font-medium text-zinc-700 dark:text-zinc-100">Живые игроки по командам</p>
          <dl class="space-y-1">
            <div
              v-for="option in winnerOptions"
              :key="option.key"
              class="flex items-center justify-between"
            >
              <dt class="text-zinc-600 dark:text-zinc-300">
                {{ option.label }}
              </dt>
              <dd class="font-semibold text-zinc-900 dark:text-white">
                {{ option.count }}
              </dd>
            </div>
            <div
              v-if="unknownCount"
              class="flex items-center justify-between pt-2 text-zinc-500 dark:text-zinc-400"
            >
              <span>Неизвестно</span>
              <span>{{ unknownCount }}</span>
            </div>
          </dl>
        </div>
        <div class="flex flex-col gap-2 sm:flex-row">
          <Toggle
            v-for="option in winnerOptions"
            :key="option.key"
            :model-value="selectedWinner === option.key"
            variant="outline"
            class="flex-1 text-sm"
            @update:model-value="(value) => handleSelection(option.key, value)"
          >
            {{ option.label }}
          </Toggle>
        </div>
        <div class="w-fulls flex">
          <Button
            type="button"
            variant="outline"
            :data-active="isAudioHolding ? 'true' : 'false'"
            :class="{
              'border-zinc-300 bg-zinc-200 text-zinc-800 shadow-none dark:border-zinc-600 dark:bg-zinc-800':
                isAudioHolding,
            }"
            class="w-full"
            :disabled="!selectedWinner"
            @pointerdown="handleAudioPointerDown"
            @pointerup="handleAudioPointerUp"
            @pointercancel="handleAudioPointerCancel"
            @pointerleave="handleAudioPointerLeave"
            @keydown.space.prevent="handleAudioKeyDown"
            @keyup.space.prevent="handleAudioKeyUp"
            @keydown.enter.prevent="handleAudioKeyDown"
            @keyup.enter.prevent="handleAudioKeyUp"
            @blur="handleAudioBlur"
          >
            <div class="flex w-full items-center justify-center gap-2">
              {{ isAudioHolding ? 'Отпустите, чтобы остановить проигрывание' : 'Звук интриги' }}
              <Icon
                :title="
                  isAudioHolding
                    ? 'icon-[tabler--player-pause-filled]'
                    : 'icon-[tabler--player-play-filled]'
                "
                class="size-4"
              />
            </div>
          </Button>
          <audio
            ref="victoryAudioRef"
            src="/audio/morning-suspence.mp3"
            preload="auto"
            loop
            class="hidden"
          />
        </div>
      </div>
      <DialogFooter class="mt-4 flex flex-col gap-2 sm:flex-row sm:justify-end">
        <Button type="button" variant="secondary" @click="handleCancel">Отмена</Button>
        <Button type="button" :disabled="!selectedWinner" @click="handleConfirm">
          Подтвердить победу
        </Button>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { storeToRefs } from 'pinia'
import { computed, ref } from 'vue'

import { useGameStore } from '@app/stores/gameStore'
import { useHoldToPlayAudio } from '@shared/lib/audio/useHoldToPlayAudio'
import type { RoleGroup } from '@processes/game-session'
import { GroupDictionary } from '@shared/config/roles'
import { Button } from '@shared/ui/button'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@shared/ui/dialog'
import { Toggle } from '@shared/ui/toggle'

const game = useGameStore()
const { aliveCountByTeam, isManualVictoryDialogOpen } = storeToRefs(game)

const TEAM_OPTIONS: RoleGroup[] = ['mafia', 'city', 'individual']

const winnerOptions = computed(() =>
  TEAM_OPTIONS.map((group) => ({
    key: group,
    label: GroupDictionary[group]?.title ?? group,
    count: aliveCountByTeam.value[group] ?? 'х/з',
  })),
)

const unknownCount = computed(() => aliveCountByTeam.value.unknown ?? 0)
const isOpen = computed(() => isManualVictoryDialogOpen.value)
const selectedWinner = ref<RoleGroup | null>(null)
const victoryAudioRef = ref<HTMLAudioElement | null>(null)

const {
  isHolding: isAudioHolding,
  handlePointerDown: handleAudioPointerDown,
  handlePointerUp: handleAudioPointerUp,
  handlePointerCancel: handleAudioPointerCancel,
  handlePointerLeave: handleAudioPointerLeave,
  handleKeyDown: handleAudioKeyDown,
  handleKeyUp: handleAudioKeyUp,
  handleBlur: handleAudioBlur,
  releaseHold: releaseAudioHold,
} = useHoldToPlayAudio({
  loopRef: victoryAudioRef,
})

const handleSelection = (group: RoleGroup, value: boolean) => {
  if (value) {
    selectedWinner.value = group
    return
  }
  if (selectedWinner.value === group) {
    selectedWinner.value = null
  }
}

const handleConfirm = () => {
  if (!selectedWinner.value) {
    return
  }
  releaseAudioHold({ playEnding: false })
  game.finishGame({ winner: selectedWinner.value })
  selectedWinner.value = null
}

const handleCancel = () => {
  releaseAudioHold({ playEnding: false })
  selectedWinner.value = null
  game.closeManualVictoryDialog()
}

const handleDialogToggle = (open: boolean) => {
  if (!open) {
    handleCancel()
  } else {
    selectedWinner.value = null
    releaseAudioHold({ playEnding: false })
  }
}
</script>
