import { EFFECTS } from '@/shared/config/effects'

const ALL_ROLES: RoleKey[] = ROLE_DEFINITIONS.map((definition) => definition.key)

export const DEFAULT_NIGHT_ROLE_ORDER: RoleKey[] = [
  'mafia',
  'prostitute',
  'maniac',
  'sheriff',
  'doctor',
  'commissar',
  'lover',
]

const dedupeRoles = (roles: RoleKey[]): RoleKey[] => {
  const seen = new Set<RoleKey>()
  return roles.filter((role) => {
    if (seen.has(role)) {
      return false
    }
    seen.add(role)
    return true
  })
}

const mergeNightOrderWithDefaults = (currentOrder: RoleKey[]): RoleKey[] => {
  const order = dedupeRoles(currentOrder)

  DEFAULT_NIGHT_ROLE_ORDER.forEach((role, defaultIndex) => {
    if (order.includes(role)) {
      return
    }

    for (let index = defaultIndex - 1; index >= 0; index -= 1) {
      const previousRole = DEFAULT_NIGHT_ROLE_ORDER[index]
      const insertionPoint = order.indexOf(previousRole)

      if (insertionPoint !== -1) {
        order.splice(insertionPoint + 1, 0, role)
        return
      }
    }

    order.unshift(role)
  })

  return order
}

const createHistoryEntryId = () => `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`

const removeNightEntryForRole = (
  history: GameHistoryEntry[],
  day: number,
  role: RoleKey,
): GameHistoryEntry[] =>
  history.filter((entry) => !(entry.phase === 'night' && entry.day === day && entry.role === role))

const appendNightHistoryEntry = (
  history: GameHistoryEntry[],
  day: number,
  role: RoleKey,
  targetId: string,
): GameHistoryEntry[] => {
  const roleDefinition = ROLE_DEFINITION_MAP[role]
  const action = roleDefinition?.ability.historyEffect

  if (!action) {
    return history
  }

  const group: RoleGroup = roleDefinition?.group ?? 'city'
  const entry: GameHistoryEntry = {
    id: createHistoryEntryId(),
    day,
    dayCount: day,
    phase: 'night',
    role,
    group,
    action,
    targetId,
    effectQuality: EFFECTS[action].quality,
    timestamp: Date.now(),
    isFatal: false,
  }

  return [...history, entry]
}

const updateNightHistoryForRole = (
  history: GameHistoryEntry[],
  day: number,
  role: RoleKey,
  targetId: string | null,
): GameHistoryEntry[] => {
  const withoutCurrent = removeNightEntryForRole(history, day, role)
  if (!targetId) {
    return withoutCurrent
  }

  return appendNightHistoryEntry(withoutCurrent, day, role, targetId)
}

const appendDayEliminationEntries = (
  history: GameHistoryEntry[],
  day: number,
  eliminations: PendingElimination[],
): GameHistoryEntry[] => {
  if (!eliminations.length) {
    return history
  }

  const timestamp = Date.now()
  const entries: GameHistoryEntry[] = eliminations.map((elimination, index) => ({
    id: createHistoryEntryId(),
    day,
    dayCount: day,
    phase: 'day' as const,
    role: null,
    group: 'city',
    action: 'eliminated' as const,
    targetId: elimination.playerId,
    timestamp: timestamp + index,
    effectQuality: 'damage',
    isFatal: true,
  }))

  return [...history, ...entries]
}

const markNightEliminationsFatal = (
  history: GameHistoryEntry[],
  eliminations: PendingElimination[],
): GameHistoryEntry[] => {
  if (!eliminations.length || history.length === 0) {
    return history
  }

  let updated = [...history]

  eliminations.forEach(({ playerId }) => {
    const index = [...updated]
      .reverse()
      .findIndex((entry) => entry.action === 'shotted' && entry.targetId === playerId)

    if (index === -1) {
      return
    }

    const originalIndex = updated.length - 1 - index
    const entry = updated[originalIndex]
    updated.splice(originalIndex, 1, { ...entry, isFatal: true })
  })

  return updated
}

const createEmptyNightActions = (): Record<RoleKey, string | null> =>
  ALL_ROLES.reduce<Record<RoleKey, string | null>>(
    (acc, role) => {
      acc[role] = null
      return acc
    },
    {} as Record<RoleKey, string | null>,
  )

const resetPlayerEffects = (players: GameSessionContext['players']) =>
  players.map((player) => ({
    ...player,
    effects: [],
  }))

const applyNightAbilities = (
  context: GameSessionContext,
  nightActions: Record<RoleKey, string | null>,
): GameSessionContext => {
  let updatedContext: GameSessionContext = {
    ...context,
    players: resetPlayerEffects(context.players),
  }

  ;(Object.entries(nightActions) as Array<[RoleKey, string | null]>).forEach(
    ([roleKey, targetId]) => {
      if (!targetId) {
        return
      }

      const ability = ROLE_DEFINITION_MAP[roleKey]?.ability

      if (!ability) {
        return
      }

      updatedContext = ability.apply(targetId, updatedContext)
    },
  )

  return updatedContext
}

const createInitialContext = (nightRoleOrder: RoleKey[]): GameSessionContext => ({
  // Счётчик полного дневного цикла, чтобы трекать текущий день игры.
  dayCount: 1,
  // Настроенный набор ролей, на основе которого создаются игроки.
  roleConfigs: [],
  // Текущий список участников со статусами.
  players: [],
  // Игроки, набравшие максимум голосов и идущие в часть итога.
  killCandidates: [],
  votingCandidates: [],
  // Очередь запланированных выбываний, которая будет применена позже.
  pendingEliminations: [],
  // Порядок ночных ролей, нужен для вращения фаз ночью.
  nightRoleOrder,
  // Роль, которая сейчас ходит ночью, если ход активен.
  currentNightRole: undefined,
  // Хранение результата победы, если победа уже определена.
  victory: null,
  // Направление и стартовый игрок для очереди монологов.
  discussionOrder: null,
  // Снимок ночных выборов каждой роли за текущую ночь.
  nightActions: createEmptyNightActions(),
  // Индекс текущей ночной роли; -1 означает, что ночь ещё не началась.
  nightRoleIndex: -1,
  isCitizenIntroPassed: false,
  monologueSpeakers: [],
  history: [],
})

type MachineOptions = {
  nightRoleOrder?: RoleKey[]
}

export type GameSessionMachineOptions = MachineOptions

const markPlayersEliminated = (
  players: GameSessionContext['players'],
  eliminations: PendingElimination[],
) =>
  players.map((player) =>
    eliminations.some((elimination) => elimination.playerId === player.id)
      ? { ...player, isAlive: false, canSpeak: false }
      : player,
  )

const gameSessionSetup = setup({
  types: {
    context: {} as GameSessionContext,
    events: {} as GameSessionEvent,
  },
  actions: {
    // Подготавливает ночь: очищает выбранные цели и возвращает указатель перед первой ролью.
    resetNightIteration: assign(({ context }) => ({
      nightRoleIndex: -1,
      currentNightRole: undefined,
      nightActions: createEmptyNightActions(),
      players: resetPlayerEffects(context.players),
      isCitizenIntroPassed: false,
    })),
    // Переставляет фокус на следующую роль в ночном порядке и сохраняет её как активную.
    advanceNightRole: assign(({ context }) => {
      const nextIndex = context.nightRoleIndex + 1
      const nextRole = context.nightRoleOrder[nextIndex]

      return {
        nightRoleIndex: nextIndex,
        currentNightRole: nextRole,
      }
    }),
    finalizeCurrentNightRole: assign(() => ({
      currentNightRole: undefined,
    })),
    // Завершает ход текущей роли и фиксирует, что дальнейших ходов ночью нет.
    clearCurrentNightRole: assign(({ context }) => ({
      nightRoleIndex: Math.max(context.nightRoleOrder.length, context.nightRoleIndex),
      currentNightRole: undefined,
      isCitizenIntroPassed: false,
    })),
    // Сохраняет целевой выбор ночной роли в контексте.
    recordNightChoice: assign(({ context, event }) => {
      if (event.type !== 'SET_NIGHT_CHOICE') {
        return {}
      }

      const nightActions = {
        ...context.nightActions,
        [event.role]: event.targetId,
      }

      const contextWithAbilities = applyNightAbilities(
        {
          ...context,
          nightActions,
        },
        nightActions,
      )

      return {
        nightActions,
        players: contextWithAbilities.players,
        history: updateNightHistoryForRole(
          context.history,
          context.dayCount,
          event.role,
          event.targetId,
        ),
      }
    }),
    // Обновляет дневные статусы перед обсуждением и очищает голосование/удаления.
    resetDayCycle: assign(({ context }) => ({
      killCandidates: [] as GameSessionContext['killCandidates'],
      votingCandidates: [] as GameSessionContext['votingCandidates'],
      pendingEliminations: [] as PendingElimination[],
      nightRoleIndex: -1,
      currentNightRole: undefined,
      isCitizenIntroPassed: false,
      players: context.players.map((player) => ({
        ...player,
        canSpeak: true,
      })),
    })),
    // Инкрементирует номер дня после завершения ночи.
    incrementDay: assign(({ context }) => ({
      dayCount: context.dayCount + 1,
    })),
    // Применяет отложенные удаления (день или ночь) к списку игроков.
    applyEliminations: assign(({ context, event }) => {
      if (event.type !== 'CONFIRM_DAY_ELIMINATION' && event.type !== 'SUBMIT_NIGHT_RESULTS') {
        return {}
      }

      const eliminations = event.eliminations
      const history =
        event.type === 'CONFIRM_DAY_ELIMINATION'
          ? appendDayEliminationEntries(context.history, context.dayCount, eliminations)
          : markNightEliminationsFatal(context.history, eliminations)

      if (!eliminations.length) {
        return {
          pendingEliminations: [] as PendingElimination[],
          players: context.players,
          history,
        }
      }

      return {
        pendingEliminations: eliminations,
        players: markPlayersEliminated(context.players, eliminations),
        history,
      }
    }),
    // Фиксирует выбранный порядок обсуждения по кнопке ведущего.
    updateDiscussionOrder: assign(({ event }) => {
      if (event.type !== 'SET_DISCUSSION_ORDER') {
        return {}
      }

      const order: DiscussionOrder = {
        firstSpeakerId: event.firstSpeakerId,
        direction: event.direction,
      }

      return {
        discussionOrder: order,
      }
    }),
    // Сбрасывает очередь монологов, когда заканчиваются итоги голосования.
    resetDiscussionOrder: assign(() => ({
      discussionOrder: null,
    })),
    // Сохраняет новую конфигурацию ролей из мастера настройки.
    configureRoles: assign(({ context, event }) => {
      if (event.type !== 'CONFIGURE_ROLES') {
        return {}
      }

      const roleConfigs: RoleConfig[] = event.data
      const configuredNightRoles = roleConfigs
        .filter((config) => config.quantity > 0 && config.role !== 'citizen')
        .map((config) => config.role)
      const uniqueNightRoles = Array.from(new Set(configuredNightRoles))
      const baseOrder = mergeNightOrderWithDefaults(context.nightRoleOrder)
      const getOrderIndex = (role: RoleKey) => {
        const index = baseOrder.indexOf(role)
        return index === -1 ? Number.MAX_SAFE_INTEGER : index
      }
      const nightRoleOrder = uniqueNightRoles.sort((a, b) => getOrderIndex(a) - getOrderIndex(b))

      return {
        roleConfigs,
        nightRoleOrder,
      }
    }),
    // Перезаписывает список игроков при регистрации или редактировании.
    registerPlayers: assign(({ event }) => {
      if (event.type !== 'REGISTER_PLAYERS') {
        return {}
      }

      return {
        players: event.data,
      }
    }),
    // Сохраняет текущие результаты голосования и вычисляет кандидатов на выбывание.
    updateVotes: assign(({ context, event }) => {
      if (event.type !== 'SUBMIT_VOTES') {
        return {}
      }

      const candidates: VoteCandidate[] = event.candidates
      const maxVotes = candidates.reduce((max, candidate) => Math.max(max, candidate.votes), 0)
      const killCandidates =
        maxVotes > 0
          ? context.players.filter((player) =>
              candidates.some(
                (candidate) => candidate.playerId === player.id && candidate.votes === maxVotes,
              ),
            )
          : []

      return {
        killCandidates,
        votingCandidates: candidates,
      }
    }),
    // Запоминает результат победы и переводит игру в завершённое состояние.
    storeVictoryResult: assign(({ event }) => {
      if (event.type !== 'DECLARE_VICTORY') {
        return {}
      }

      return {
        victory: event.result,
      }
    }),
    // Позволяет вручную завершить игру через диалог ведущего.
    finishGameManually: assign(({ event }) => {
      if (event.type !== 'FINISH_GAME') {
        return {}
      }

      return {
        victory: event.result ?? null,
      }
    }),
    // Оставляет право говорить только у кандидатов, прошедших голосование, и отключает остальных.
    restrictSpeakersAfterVoting: assign(({ context }) => {
      const updatedPlayers = context.players.map((player) => {
        if (context.killCandidates.some((candidate) => candidate.id === player.id)) {
          return {
            ...player,
            canSpeak: true,
          }
        }

        return {
          ...player,
          canSpeak: false,
        }
      })

      return {
        players: updatedPlayers,
      }
    }),
    // После любой фазы проверяет, не наступила ли чья-либо победа.
    evaluateVictoryAfterPhase: assign(({ context }) => ({
      victory: evaluateVictory(context),
    })),
    // Очищает флаг победы при запуске нового раунда.
    clearVictory: assign(() => ({
      victory: null,
    })),
    // Полностью возвращает контекст к началу игры, сохранив порядок ночных ролей.
    resetGameContext: assign(({ context }) => {
      const resetContext = createInitialContext(context.nightRoleOrder)

      return resetContext
    }),
    resetMonologueSpeakers: assign(() => ({
      monologueSpeakers: [],
    })),
    resetVotingCandidates: assign(() => ({
      votingCandidates: [],
    })),
    toggleCitizenIntroPassed: assign(() => ({
      isCitizenIntroPassed: true,
    })),
  },
  guards: {
    // Проверяет, есть ли уже рассчитанный победитель, чтобы завершить игру.
    hasVictory: ({ context }) => Boolean(context.victory),
    // Сообщает, что остались роли, которым ещё нужно дать ход в эту ночь.
    hasMoreNightRoles: ({ context }) => context.nightRoleIndex + 1 < context.nightRoleOrder.length,
    // Фильтрует действия SET_NIGHT_CHOICE, чтобы роль не выбирала чужие цели.
    matchesCurrentNightRole: ({ context, event }) =>
      event.type === 'SET_NIGHT_CHOICE' && event.role === context.currentNightRole,
    ifCitizenStartNeeded: ({ context }) => {
      const nextNightRole = context.nightRoleOrder[context.nightRoleIndex + 1]
      return citizenRolesThatNeededIntro.includes(nextNightRole) && !context.isCitizenIntroPassed
    },
    isCitizenEndNeeded: ({ context }) => {
      return !context.nightRoleOrder.includes('lover')
    },
  },
})

