import { EffectKey, GameSessionContext, RoleAbility, RoleKey } from '../types'

const createBasicRoleAbility = (effectKey: EffectKey) => ({
  historyEffect: effectKey,
  apply: (playerId: string, context: GameSessionContext) => ({
    ...context,
    players: context.players.map((player) => {
      if (player.id !== playerId) {
        return player
      }

      if (player.effects.includes(effectKey)) {
        return player
      }

      return {
        ...player,
        effects: [...player.effects, effectKey],
      }
    }),
  }),
  undo: (playerId: string, context: GameSessionContext) => ({
    ...context,
    players: context.players.map((player) => {
      if (player.id !== playerId) {
        return player
      }

      if (!player.effects.includes(effectKey)) {
        return player
      }

      return {
        ...player,
        effects: player.effects.filter((effect) => effect !== effectKey),
      }
    }),
  }),
})

