import { computed, ref, type Ref } from 'vue'

export type SnapshotHistoryAdapter<TSnapshot, TEntry> = {
  capture: (snapshot: TSnapshot) => TEntry
  restore: (entry: TEntry) => TSnapshot
  areEqual?: (a: TEntry, b: TEntry) => boolean
}

export type SnapshotHistoryOptions = {
  capacity?: number
}

export const createSnapshotHistory = <TSnapshot, TEntry>(
  adapter: SnapshotHistoryAdapter<TSnapshot, TEntry>,
  options: SnapshotHistoryOptions = {},
) => {
  const past: Ref<TEntry[]> = ref([])
  const future: Ref<TEntry[]> = ref([])
  const current: Ref<TEntry | null> = ref(null)
  const isRestoring = ref(false)
  const capacity = options.capacity ?? 100

  const areEqual = adapter.areEqual ?? ((a: TEntry, b: TEntry) => a === b)

  const bootstrap = (snapshot: TSnapshot) => {
    current.value = adapter.capture(snapshot)
    past.value = []
    future.value = []
    isRestoring.value = false
  }

  const record = (snapshot: TSnapshot) => {
    const entry = adapter.capture(snapshot)

    if (isRestoring.value) {
      current.value = entry
      isRestoring.value = false
      return
    }

    if (!current.value) {
      current.value = entry
      return
    }

    if (areEqual(current.value, entry)) {
      return
    }

    if (past.value.length >= capacity) {
      past.value.shift()
    }
    past.value.push(current.value)
    current.value = entry
    future.value = []
  }

  const undo = (): TSnapshot | null => {
    const currentEntry = current.value
    if (!past.value.length || !currentEntry) {
      return null
    }

    const previous = past.value.pop()
    if (!previous) {
      return null
    }

    future.value.push(currentEntry)
    current.value = previous
    isRestoring.value = true

    return adapter.restore(previous)
  }

  const redo = (): TSnapshot | null => {
    const currentEntry = current.value
    if (!future.value.length || !currentEntry) {
      return null
    }

    const next = future.value.pop()
    if (!next) {
      return null
    }

    past.value.push(currentEntry)
    current.value = next
    isRestoring.value = true

    return adapter.restore(next)
  }

  const acknowledge = (snapshot: TSnapshot) => {
    current.value = adapter.capture(snapshot)
    isRestoring.value = false
  }

  const reset = (snapshot: TSnapshot) => {
    bootstrap(snapshot)
  }

  const canUndo = computed(() => past.value.length > 0)
  const canRedo = computed(() => future.value.length > 0)
  const isApplyingFromHistory = computed(() => isRestoring.value)

  return {
    record,
    undo,
    redo,
    bootstrap,
    acknowledge,
    reset,
    canUndo,
    canRedo,
    isRestoring: isApplyingFromHistory,
  }
}
