type ReleaseOptions = {
  playEnding?: boolean
}

type SuspenseControlHandle = {
  engage: () => boolean
  release: (options?: ReleaseOptions) => boolean
  cancel?: () => boolean
  isActive: () => boolean
}

let currentControl: SuspenseControlHandle | null = null

export const suspenseAudioController = {
  register(control: SuspenseControlHandle) {
    currentControl = control
    return () => {
      if (currentControl === control) {
        currentControl = null
      }
    }
  },
  engage() {
    if (!currentControl) {
      return false
    }
    return currentControl.engage()
  },
  release(options?: ReleaseOptions) {
    if (!currentControl) {
      return false
    }
    return currentControl.release(options)
  },
  cancel() {
    if (!currentControl || !currentControl.cancel) {
      return false
    }
    return currentControl.cancel()
  },
  isActive() {
    return currentControl?.isActive() ?? false
  },
}
