<script setup lang="ts">
import GameHistoryTable from '../../../features/game/show-game-history/GameHistoryTable.vue'
import { AssignRolesDialog } from '@/features/game/assign-roles'
import { ManualVictoryDialog } from '@/features/game/manual-victory'
import { GameHistoryDialog } from '@/features/game/show-game-history'
import { useGameStore } from '@app/stores/gameStore'
import { PlayerCard } from '@entities/player'
import { NightResultsSuspenseControl } from '@features/game/night-results-suspense'
import { SetRoleDialog } from '@features/game/set-role'
import type {
  PlayerSlot,
  RoleConfig,
  RoleGroup,
  RoleKey,
  VictoryResult,
} from '@processes/game-session'
import { ROLE_DEFINITIONS } from '@shared/config/roles'
import { encodeSnapshot } from '@shared/lib/snapshotLink'
import { Button } from '@shared/ui/button'
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@shared/ui/dialog'
import { storeToRefs } from 'pinia'
import QrcodeVue from 'qrcode.vue'
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { joinURL } from 'ufo'
import RoleSummaryTable from '../../../features/game/show-role-list/RoleSummaryTable.vue'
import { usePlayerEditing } from '../model/usePlayerEditing'
import GameScreenFooter from './GameScreenFooter.vue'
import GameScreenHeader from './GameScreenHeader.vue'

const props = defineProps<{
  roleConfigs: RoleConfig[]
  initialPlayers: PlayerSlot[]
}>()

const emit = defineEmits<{
  finish: [VictoryResult | null]
  reset: []
}>()

const game = useGameStore()
const router = useRouter()
const {
  currentStageKey,
  players,
  dayCount,
  currentNightRole,
  nightActions,
  eligibleSpeakers,
  firstSpeaker,
  canContinue,
  canResetToDiscussion,
  isNightRoleTurn,
  isNightResults,
  isVoting,
  isVotingResults,
  isMonologues,
  isGameOver,
  voteInputs,
  pendingEliminations,
  pendingRoleAssignment,
  hasPersistedSession,
  isRoleSelectionMode,
  victory,
  victoryLabel,
  victoryPlayer,
  victoryRoleDefinition,
  history,
} = storeToRefs(game)

const playerListRef = ref<HTMLElement | null>(null)

const { startEdit, cancelEdit, commitEdit, isEditingPlayer } = usePlayerEditing({
  players,
  currentStageKey,
  isRoleSelectionMode,
  focusContainer: playerListRef,
  renamePlayer: (playerId: string, name: string) => game.renamePlayer(playerId, name),
})

const roleSelection = ref<RoleKey | ''>('')

const isRoleDialogOpen = computed(() => Boolean(pendingRoleAssignment.value))
const ROLE_NONE_VALUE = '__none__'

watch(pendingRoleAssignment, (next, previous) => {
  if (next?.playerId !== previous?.playerId) {
    roleSelection.value = ''
  }
})

const setVote = (playerId: string, value: number) => {
  game.setVote(playerId, Number.isFinite(value) ? Math.max(0, value) : 0)
}

const toggleElimination = (playerId: string, type: 'day' | 'night') => {
  void type
  game.toggleElimination(playerId, 'day')
}

const togglePlayerCanSpeak = (playerId: string, value: boolean) => {
  game.togglePlayerCanSpeak(playerId, value)
}

const togglePlayerGoldenMinute = (playerId: string, value: boolean) => {
  game.togglePlayerGoldenMinute(playerId, value)
}

const isSelectedNightTarget = (playerId: string) => {
  if (!currentNightRole.value) {
    return false
  }
  return nightActions.value[currentNightRole.value] === playerId
}

const isEliminationSelected = (playerId: string) => pendingEliminations.value.includes(playerId)

const nightActionLabel = computed(() => {
  if (!currentNightRole.value) {
    return 'Выберите цель'
  }
  const role = ROLE_DEFINITIONS.find((definition) => definition.key === currentNightRole.value)
  return role ? `Ход роли: ${role.label}` : 'Ход ночной роли'
})

const victoryButtonText = computed(() => {
  if (!victory.value) {
    return null
  }
  const label =
    victoryLabel.value ?? victoryPlayer.value?.name ?? victoryRoleDefinition.value?.label ?? ''
  if (!label) {
    return null
  }
  return `Победили ${label}. Завершить игру?`
})

const confirmDayEliminations = () => {
  game.confirmDayEliminations()
}

const confirmNightEliminations = () => {
  game.confirmNightEliminations()
}

const handleConfirmEliminations = () => {
  if (isVotingResults.value) {
    confirmDayEliminations()
  } else {
    confirmNightEliminations()
  }
}

const chooseRandomSpeaker = () => {
  game.chooseRandomSpeaker()
}

const selectNightTarget = (role: RoleKey, targetId: string | null) => {
  const current = nightActions.value[role] ?? null
  const nextTarget = current === targetId ? null : targetId
  game.selectNightTarget(nextTarget)
}

const completeNightRole = () => {
  game.completeNightRole()
}

const handleContinue = () => {
  game.continueStage()
}

const handleRestartNight = () => {
  game.restartNight()
}

const handleReturnToMonologues = () => {
  game.returnToMonologues()
}

const handleResetToDiscussion = () => {
  game.resetToDiscussion()
}

const pendingRoleReasonLabel = computed(() => {
  if (!pendingRoleAssignment.value) {
    return ''
  }
  return pendingRoleAssignment.value.type === 'day' ? 'днём' : 'ночью'
})

const handleRoleDialogToggle = (open: boolean) => {
  if (!open && pendingRoleAssignment.value) {
    handleCancelRoleAssignment()
  }
}

const handleConfirmRoleAssignment = () => {
  if (!roleSelection.value) {
    return
  }

  game.confirmPendingRole(roleSelection.value as RoleKey)
  roleSelection.value = ''
}

const handleCancelRoleAssignment = () => {
  roleSelection.value = ''
  game.cancelRoleAssignment()
}

const handleOpenRoleSelection = () => {
  game.openRoleSelection()
}

const handleOpenManualVictory = () => {
  game.openManualVictoryDialog()
}

const handleCompleteWithVictory = () => {
  if (!victory.value) {
    return
  }
  game.finishGame(victory.value)
}

const handleResetGame = () => {
  game.resetGame()
  emit('reset')
}

const helperLink = ref<string | null>(null)
const isHelperDialogOpen = ref(false)

const selectHelperLink = (event: Event) => {
  const target = event.target as HTMLTextAreaElement | null
  target?.select()
}

const HELPER_BASE_URL_FALLBACK = 'http://192.168.1.73:5177'

const ensureProtocol = (value: string): string => {
  if (/^[a-zA-Z][\w+.-]*:\/\//u.test(value)) {
    return value
  }
  return `http://${value}`
}

const sanitizeBaseUrl = (value: string | null | undefined): string | null => {
  if (!value) {
    return null
  }
  const trimmed = value.trim()
  if (!trimmed) {
    return null
  }

  try {
    const url = new URL(ensureProtocol(trimmed))
    url.hash = ''
    url.search = ''
    return url.toString().replace(/\/+$/, '')
  } catch {
    return null
  }
}

const resolveHelperBaseUrl = (): string => {
  const envValue = sanitizeBaseUrl(import.meta.env.VITE_HELPER_BASE_URL)
  if (envValue) {
    return envValue
  }

  if (typeof window !== 'undefined') {
    const windowBase = sanitizeBaseUrl(window.location.origin)
    if (windowBase) {
      return windowBase
    }
  }

  return sanitizeBaseUrl(HELPER_BASE_URL_FALLBACK) ?? HELPER_BASE_URL_FALLBACK
}

const buildHelperLink = (encoded: string): string => {
  const baseUrl = resolveHelperBaseUrl()
  const helperHref = router.resolve({ path: '/helper', query: { snapshot: encoded } }).href
  return joinURL(baseUrl, helperHref)
}

const handleOpenHelperLink = () => {
  if (typeof window === 'undefined') {
    return
  }

  const session = game.createSessionSnapshot()
  const encoded = encodeSnapshot(session)
  helperLink.value = buildHelperLink(encoded)
  isHelperDialogOpen.value = true
}

const handleHelperDialogToggle = (open: boolean) => {
  isHelperDialogOpen.value = open
  if (!open) {
    helperLink.value = null
  }
}

onMounted(() => {
  if (hasPersistedSession.value) {
    return
  }
  game.initializeGame(props.roleConfigs, props.initialPlayers)
})

watch(
  () => isGameOver.value,
  (gameOver) => {
    if (gameOver) {
      emit('finish', victory.value ?? null)
    }
  },
)

const isDeadPlayersExpanded = ref(false)

const blockedPlayers = computed(() => {
  return game.players
    .filter((player) => player.effects.includes('blocked'))
    .map((player) => {
      const roleDef = ROLE_DEFINITIONS.find((definition) => player.role?.includes(definition.key))
      return {
        playerName: player.name,
        roleTitle: roleDef?.label ?? null,
        roleKey: roleDef?.key ?? null,
      }
    })
    .filter((player) => player.roleKey !== 'citizen')
})
const blockedRoleKeys = computed(() =>
  blockedPlayers.value.map((player) => player.roleKey).filter((key) => key !== null),
)

const checkedPlayer = computed(() => {
  return game.players.find((player) => player.effects.includes('checked'))
})

const isCheckedPlayerBad = computed(() => {
  if (!checkedPlayer.value) return null

  const roleKey = checkedPlayer.value?.role
  if (!roleKey) return null
  const roleDef = ROLE_DEFINITIONS.find((definition) => definition.key === roleKey)!
  return (['mafia', 'individual'] as RoleGroup[]).includes(roleDef.group)
})

const sortedPlayers = computed(() =>
  [...game.alivePlayers].sort((a, b) => (dayCount.value % 2 === 0 ? -1 : 1)),
)

const handleOpenHistory = () => {
  game.isHistoryDialogOpen = true
}
</script>
