<template>
  <div class="flex flex-col gap-3">
    <Button
      type="button"
      variant="outline"
      :data-active="isHolding ? 'true' : 'false'"
      :class="{ 'border-zinc-200 bg-zinc-200 shadow-none': isHolding }"
      @pointerdown="handlePointerDown"
      @pointerup="handlePointerUp"
      @pointercancel="handlePointerCancel"
      @pointerleave="handlePointerLeave"
      @keydown.space.prevent="handleKeyDown"
      @keyup.space.prevent="handleKeyUp"
      @keydown.enter.prevent="handleKeyDown"
      @keyup.enter.prevent="handleKeyUp"
      @blur="handleBlur"
    >
      <div class="flex w-full items-center justify-center gap-2">
        {{ isHolding ? 'Отпустить для завершения эффекта' : 'Проиграть нагнетающий звук' }}
        <Icon v-if="!isHolding" title="icon-[tabler--player-play-filled]" class="size-4" />
        <Icon v-else title="icon-[tabler--player-pause-filled]" class="size-4" />
      </div>
      <Kbd>S</Kbd>
    </Button>

    <audio
      ref="suspenseAudioRef"
      :src="resolveInternalLink('/audio/morning-suspence.mp3')"
      preload="auto"
      loop
      class="hidden"
    />
    <audio
      ref="endingAudioRef"
      :src="resolveInternalLink('/audio/morning-suspence-end.mp3')"
      preload="auto"
      class="hidden"
    />
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue'

import { useHoldToPlayAudio } from '@/shared/lib/audio/useHoldToPlayAudio'
import { Button } from '@/shared/ui/button'
import { resolveInternalLink } from '@/shared/lib/utils'

const suspenseAudioRef = ref<HTMLAudioElement | null>(null)
const endingAudioRef = ref<HTMLAudioElement | null>(null)

const {
  isHolding,
  handlePointerDown,
  handlePointerUp,
  handlePointerCancel,
  handlePointerLeave,
  handleKeyDown,
  handleKeyUp,
  handleBlur,
} = useHoldToPlayAudio({
  loopRef: suspenseAudioRef,
  endingRef: endingAudioRef,
  registerController: true,
})
</script>
