import { onBeforeUnmount, onMounted } from 'vue'
import { audioController } from '@/shared/lib/audio/audioController'
import { suspenseAudioController } from '@/shared/lib/audio/suspenseAudioController'
import { gameKeyboardShortcuts } from './config'
import type {
  KeyboardShortcut,
  KeyboardShortcutHandlers,
  ShortcutAction,
} from './types'

const EDITABLE_TAGS = new Set(['INPUT', 'TEXTAREA', 'SELECT'])

const matchesModifier = (value: boolean, expected?: boolean) => {
  if (typeof expected === 'boolean') {
    return value === expected
  }
  return value === false
}

const matchesShortcut = (event: KeyboardEvent, shortcut: KeyboardShortcut) =>
  event.code === shortcut.code &&
  matchesModifier(event.shiftKey, shortcut.shiftKey) &&
  matchesModifier(event.altKey, shortcut.altKey) &&
  matchesModifier(event.ctrlKey, shortcut.ctrlKey) &&
  matchesModifier(event.metaKey, shortcut.metaKey)

const isEditableTarget = (target: EventTarget | null) => {
  if (!(target instanceof HTMLElement)) {
    return false
  }

  if (target.isContentEditable) {
    return true
  }

  if (EDITABLE_TAGS.has(target.tagName)) {
    return true
  }

  return Boolean(target.closest('[data-keyboard-shortcuts="ignore"]'))
}

const shouldIgnoreEvent = (event: KeyboardEvent, shortcut: KeyboardShortcut) => {
  if (event.repeat) {
    return true
  }

  if (event.defaultPrevented) {
    return true
  }

  if (!shortcut.allowInEditable && isEditableTarget(event.target)) {
    return true
  }

  return false
}

const handleAudioAction = (action: Extract<ShortcutAction, 'restartAudio' | 'togglePlayback'>) => {
  if (action === 'restartAudio') {
    audioController.restart()
    return
  }

  audioController.togglePlayback()
}

const createActionHandler = (handlers: KeyboardShortcutHandlers) => {
  return (action: ShortcutAction) => {
    if (action === 'nextStage') {
      const advanced = handlers.nextStage.tryAutoAdvanceStage()
      if (!advanced && handlers.nextStage.canContinue()) {
        handlers.nextStage.continueStage()
      }
      return
    }

    if (action === 'undo') {
      if (handlers.history.canUndo()) {
        handlers.history.undo()
      }
      return
    }

    if (action === 'redo') {
      if (handlers.history.canRedo()) {
        handlers.history.redo()
      }
      return
    }

    if (action === 'suspense') {
      return
    }

    handleAudioAction(action)
  }
}

export const useGameKeyboardShortcuts = (handlers: KeyboardShortcutHandlers) => {
  const handleAction = createActionHandler(handlers)
  const suspenseShortcut = gameKeyboardShortcuts.find(
    (shortcut) => shortcut.action === 'suspense',
  )
  let suspenseEngagedByKeyboard = false

  const listener = (event: KeyboardEvent) => {
    const shortcut = gameKeyboardShortcuts.find((item) => matchesShortcut(event, item))
    if (!shortcut) {
      return
    }

    if (shouldIgnoreEvent(event, shortcut)) {
      return
    }

    if (shortcut.preventDefault !== false) {
      event.preventDefault()
    }

    if (shortcut.action === 'suspense') {
      if (suspenseEngagedByKeyboard) {
        return
      }
      suspenseEngagedByKeyboard = suspenseAudioController.engage()
      return
    }

    handleAction(shortcut.action)
  }

  const suspenseKeyupListener = (event: KeyboardEvent) => {
    if (!suspenseShortcut) {
      return
    }
    if (!matchesShortcut(event, suspenseShortcut)) {
      return
    }
    if (!suspenseEngagedByKeyboard) {
      return
    }

    suspenseAudioController.release()
    suspenseEngagedByKeyboard = false
  }

  onMounted(() => {
    if (typeof window === 'undefined') {
      return
    }
    window.addEventListener('keydown', listener)
    window.addEventListener('keyup', suspenseKeyupListener)
  })

  onBeforeUnmount(() => {
    if (typeof window === 'undefined') {
      return
    }
    window.removeEventListener('keydown', listener)
    window.removeEventListener('keyup', suspenseKeyupListener)
  })
}
