<template>
  <div ref="rootElement">
    <div
      v-if="gameHistory.historyRows.length === 0"
      class="p-2x-2 rounded-lg border border-zinc-300 py-6 text-center text-xs text-zinc-500 dark:border-zinc-700 dark:text-zinc-400"
    >
      Записей пока нет
    </div>
    <div v-else class="grid grid-cols-[minmax(max-content,auto)_1fr_1fr] gap-x-3 gap-y-4">
      <template v-for="[dayCount, historyRows] in Object.entries(historyRowsByDay)" :key="dayCount">
        <div class="col-span-full mt-3 text-sm font-semibold text-zinc-400 first:mt-0">
          День {{ dayCount }}
        </div>
        <div v-for="row in historyRows" :key="row.id" class="contents text-sm">
          <div class="relative">
            <div class="relative z-10 inline w-fit bg-white pr-3 text-zinc-600">
              {{ row.roleLabel }}
              <span v-if="row.players?.length === 1" class="text-zinc-900"
                >[{{ row.players[0].name }}]</span
              >
            </div>
            <div
              :class="
                row.effectQuality === 'positive'
                  ? 'text-green-500'
                  : row.effectQuality === 'negative'
                    ? 'text-amber-500'
                    : row.effectQuality === 'neutral'
                      ? 'text-zinc-500'
                      : row.effectQuality === 'damage'
                        ? 'text-red-500'
                        : ''
              "
              class="absolute top-[11px] -right-3 z-0 w-full border-b border-current/30"
            />
          </div>
          <div
            class="relative flex w-full justify-center text-center"
            :class="
              row.effectQuality === 'positive'
                ? 'text-green-500'
                : row.effectQuality === 'negative'
                  ? 'text-amber-500'
                  : row.effectQuality === 'neutral'
                    ? 'text-zinc-500'
                    : row.effectQuality === 'damage'
                      ? 'text-red-500'
                      : ''
            "
          >
            <i class="absolute -top-[3px] text-[10px] opacity-80">
              {{ actionTitleDictionary[row.action] }}
            </i>
            <div class="absolute top-[11px] w-full border-b border-current/30" />
            <div class="absolute top-[8px] right-[5px] h-1/2 w-px rotate-[75deg] bg-current/30" />
            <div class="absolute top-[5px] right-[5px] h-1/2 w-px rotate-[-75deg] bg-current/30" />
          </div>
          <div
            class="flex items-center gap-1 text-start"
            :class="
              row.effectQuality === 'positive'
                ? 'text-green-500'
                : row.effectQuality === 'negative'
                  ? 'text-amber-500'
                  : row.effectQuality === 'neutral'
                    ? 'text-zinc-500'
                    : row.effectQuality === 'damage'
                      ? 'text-red-500'
                      : ''
            "
          >
            <span class="font-medium">
              {{ row.targetName }}
            </span>
            <span
              v-if="row.targetId && game.roleKeyByPlayerIdMap[row.targetId]"
              class="whitespace-nowrap text-zinc-500"
              >({{ game.roleDefByKeyMap[game.roleKeyByPlayerIdMap[row.targetId]!].label }})</span
            >
            <Icon v-if="row.isFatal" title="icon-[tabler--skull]" class="size-4 min-w-4"></Icon>
          </div>
        </div>
      </template>
      <div v-if="victorySummary" class="b col-span-full mt-6 py-5 text-sm shadow-sm">
        <div class="text-xs font-semibold tracking-wide text-zinc-400 uppercase">Итог игры</div>
        <div class="mt-3 grid grid-cols-3 space-y-2">
          <div
            v-for="team in victorySummary.teams"
            :key="team.key"
            class="flex justify-center gap-x-2 first:justify-start last:justify-end"
          >
            <span class="text-zinc-500"
              >{{ team.key === 'individual' ? 'Маньяк' : team.label }}:</span
            >
            <span class="font-semibold text-zinc-900">{{ team.count }}</span>
          </div>
        </div>
        <div class="mt-2 border-t border-zinc-200 pt-3 text-sm text-zinc-600">
          Победитель:
          <span class="font-semibold text-zinc-900">{{ victorySummary.winnerTitle }}</span>
          <span v-if="victorySummary.winnerSuffix" class="ml-1 text-zinc-500">
            {{ victorySummary.winnerSuffix }}
          </span>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { useGameStore } from '@/app/stores/gameStore'
import { GameHistoryAction } from '@/processes/game-session/model/types'
import { GroupDictionary, GROUP_KEYS } from '@/shared/config/roles'
import { computed, ref } from 'vue'
import { useGameHistory } from './useGameHistory'

const gameHistory = useGameHistory()
const game = useGameStore()

const actionTitleDictionary = {
  shotted: 'Стреляет',
  checked: 'Проверяет',
  healed: 'Лечит',
  blocked: 'Блокирует',
  habilitated: 'Даёт алиби',
  eliminated: 'Выгоняют',
} satisfies Record<GameHistoryAction, string>

const historyRowsByDay = gameHistory.historyRows.reduce<
  Record<number, typeof gameHistory.historyRows>
>(
  (acc, row) => {
    acc[row.dayCount] = [...(acc[row.dayCount] ?? []), row]
    return acc
  },
  {} as Record<number, typeof gameHistory.historyRows>,
)

const victorySummary = computed(() => {
  const result = game.victory
  if (!result) {
    return null
  }

  const teams = GROUP_KEYS.filter((group) => group in game.aliveCountByTeam).map((group) => ({
    key: group,
    label: GroupDictionary[group].title,
    count: game.aliveCountByTeam[group] ?? 0,
  }))

  const winnerTitle =
    result.winner === 'individual' ? 'Маньяк' : (GroupDictionary[result.winner]?.title ?? '—')

  const winnerSuffix =
    result.winner === 'individual'
      ? `(${result.playerName ?? game.victoryPlayer?.name ?? 'Неизвестный игрок'})`
      : null

  return {
    teams,
    winnerTitle,
    winnerSuffix,
  }
})

const rootElement = ref<HTMLElement | null>(null)

defineExpose({
  rootElement,
})

export type GameHistoryTableExpose = {
  rootElement: HTMLElement | null
}
</script>
