<template>
  <div class="flex h-screen items-center justify-center">
    <section class="container flex w-md max-w-xl flex-col gap-6">
      <header class="space-y-1 px-1">
        <h2 class="text-3xl font-semibold">Cостав ролей</h2>
      </header>
      <div>
        <form class="flex flex-col gap-6" @submit.prevent="handleSubmit">
          <div class="grid gap-6 px-1 md:grid-cols-1">
            <div class="flex flex-col gap-1">
              <div class="flex items-center justify-between gap-4 rounded-lg">
                <div>
                  <p class="text-base font-medium">Доступные игроки</p>
                </div>
                <div class="flex items-center gap-2">
                  <span class="text-sm text-zinc-400">{{ totalRolesCount }} /</span>
                  <InputNumber
                    id="availablePlayers"
                    v-model.number="availablePlayersCount"
                    :min="MIN_AVAILABLE_PLAYERS"
                    :max="MAX_AVAILABLE_PLAYERS"
                  />
                </div>
              </div>
            </div>
            <div
              v-for="([key, group], index) in definitionsByGroup"
              :key="index"
              class="flex flex-col gap-1"
            >
              <div class="pb-1 text-sm font-medium text-zinc-400">
                {{ GroupDictionary[key].title }}
              </div>

              <div
                v-for="definition in group"
                :key="definition.key"
                class="flex items-center justify-between gap-4 rounded-lg"
              >
                <div>
                  <TooltipProvider>
                    <Tooltip>
                      <TooltipTrigger>
                        <p class="flex items-center text-base font-medium">
                          {{ definition.label }}
                          <Icon
                            title="icon-[tabler--question-circle]"
                            class="ize-4 ml-1 text-zinc-400"
                          />
                        </p>
                      </TooltipTrigger>
                      <TooltipContent> {{ definition.description }}</TooltipContent>
                    </Tooltip>
                  </TooltipProvider>
                </div>
                <div class="flex items-center gap-2">
                  <InputNumber
                    v-model.number="roleCounts[definition.key]"
                    type="number"
                    :min="0"
                    :max="getMaxForRole(definition.key)"
                  />
                </div>
              </div>
            </div>
          </div>
          <div class="flex flex-wrap justify-end gap-3">
            <Button
              type="submit"
              class="inline-flex w-full items-center gap-2 rounded-lg bg-black px-4 py-2 text-sm font-semibold text-slate-50 shadow-lg shadow-zinc-500/30 transition hover:bg-zinc-400 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-zinc-300"
              :disabled="!isValid"
            >
              Играть →
            </Button>
          </div>
        </form>
      </div>
    </section>
  </div>
</template>

<script setup lang="ts">
import { InputNumber } from '@/shared/ui'
import Button from '@/shared/ui/button/Button.vue'
import type { RoleConfig, RoleGroup, RoleKey } from '@processes/game-session'
import { GroupDictionary, ROLE_DEFINITIONS } from '@shared/config/roles'
import _ from 'lodash'
import { computed, reactive, ref } from 'vue'

const emit = defineEmits<{
  configured: [RoleConfig[]]
  canceled: []
}>()

const MIN_AVAILABLE_PLAYERS = 4
const MAX_AVAILABLE_PLAYERS = 20

const roleCounts = reactive<Record<RoleKey, number>>(
  // ROLE_DEFINITIONS.reduce<Record<RoleKey, number>>((acc, item) => {
  //   acc[item.key] = 0
  //   return acc
  // }, {} as Record<RoleKey, number>),
  {
    mafia: 3,
    prostitute: 0,
    citizen: 3,
    sheriff: 1,
    doctor: 1,
    commissar: 1,
    lover: 0,
    maniac: 1,
  },
)

const availablePlayersCount = ref(10)

const totalRolesCount = computed(() =>
  Object.values(roleCounts).reduce((sum, count) => sum + count, 0),
)

const getMaxForRole = (role: RoleKey) => {
  const otherRolesTotal = totalRolesCount.value - (roleCounts[role] ?? 0)
  const remainingSlots = availablePlayersCount.value - otherRolesTotal
  return Math.max(remainingSlots, 0)
}

// const groupLabels: Record<(typeof ROLE_DEFINITIONS)[number]['group'], string> =
//   {
//     mafia: 'Клан мафии',
//     city: 'Горожане',
//     individual: 'Сами за себя',
//   } as const

// const changeCount = (role: RoleKey, delta: number) => {
//   const next = Math.max(0, (roleCounts[role] ?? 0) + delta)
//   roleCounts[role] = next
// }

const isValid = computed(
  () =>
    totalRolesCount.value === availablePlayersCount.value &&
    availablePlayersCount.value >= MIN_AVAILABLE_PLAYERS &&
    availablePlayersCount.value <= MAX_AVAILABLE_PLAYERS,
)
const handleSubmit = () => {
  if (!isValid.value) return
  const configs = ROLE_DEFINITIONS.map<RoleConfig>((definition) => ({
    role: definition.key,
    quantity: roleCounts[definition.key] ?? 0,
  })).filter((config) => config.quantity > 0)

  emit('configured', configs)
}

const definitionsByGroup = _(ROLE_DEFINITIONS)
  .groupBy((definition) => definition.group)
  .toPairs()
  .value() as [RoleGroup, typeof ROLE_DEFINITIONS][]
</script>
