import { ROLE_DEFINITION_MAP, ROLE_DEFINITIONS } from '@shared/config/roles'
import type { GameSessionContext, VictoryResult, RoleKey, RoleGroup } from './types'

export const evaluateVictory = (context: GameSessionContext): VictoryResult | null => {
  const alivePlayers = context.players.filter((player) => player.isAlive)

  if (!alivePlayers.length) {
    return null
  }

  const groupOf = (role: RoleKey | null | undefined): RoleGroup | null => {
    if (!role) {
      return null
    }
    return ROLE_DEFINITION_MAP[role]?.group ?? null
  }

  const configuredRoleMap = context.roleConfigs.reduce<Record<RoleKey, number>>(
    (acc, config) => {
      acc[config.role] = config.quantity
      return acc
    },
    {} as Record<RoleKey, number>,
  )

  const assignedRoleCounts = context.players.reduce<Partial<Record<RoleKey, number>>>(
    (acc, player) => {
      if (player.role) {
        acc[player.role] = (acc[player.role] ?? 0) + 1
      }
      return acc
    },
    {},
  )

  const remainingSlotsForGroup = (group: RoleGroup) => ROLE_DEFINITIONS.filter((definition) => definition.group === group).reduce((total, role) => {
    const configured = configuredRoleMap[role.key] ?? 0
    const assigned = assignedRoleCounts[role.key] ?? 0
    return total + Math.max(0, configured - assigned)
  }, 0)

  const mafiaAlive = alivePlayers.some((player) => groupOf(player.role) === 'mafia')
  const cityAlive = alivePlayers.some((player) => groupOf(player.role) === 'city')
  const individualAlive = alivePlayers.filter((player) => groupOf(player.role) === 'individual')
  const unknownAlive = alivePlayers.filter((player) => groupOf(player.role) === null)

  if (individualAlive.length === 1 && alivePlayers.length === 1) {
    const winner = individualAlive[0]
    return {
      winner: 'individual',
      role: winner.role ?? undefined,
      playerId: winner.id,
      playerName: winner.name,
    }
  }

  if (mafiaAlive &&
    !cityAlive &&
    individualAlive.length === 0 &&
    unknownAlive.length === 0) {
    return {
      winner: 'mafia',
    }
  }

  const remainingMafiaSlots = remainingSlotsForGroup('mafia')
  const remainingIndividualSlots = remainingSlotsForGroup('individual')

  if (!mafiaAlive && individualAlive.length === 0 && alivePlayers.length > 0) {
    if (remainingMafiaSlots === 0 && remainingIndividualSlots === 0) {
      return {
        winner: 'city',
      }
    }
  }

  return null
}
