<template>
  <article
    :class="[
      'relative flex h-12 rounded-lg border border-zinc-300 bg-zinc-50 px-2 shadow-zinc-500/10 transition focus-within:ring-2',
      'focus-within:ring-zinc-300 dark:border-zinc-700 dark:bg-zinc-800 dark:text-white dark:shadow-zinc-900/20',
      {
        'opacity-50': !player.isAlive,
        'shadow-xs hover:shadow-md': player.isAlive,
      },
    ]"
  >
    <header class="flex flex-1 items-center justify-between gap-2">
      <PlayerEditForm
        v-if="isEditing || !player.name"
        :model-value="player"
        @submit="handleSubmit"
        @cancel="emit('cancel-edit')"
      />

      <Button
        v-else
        class="group flex items-center px-3 py-1.5 font-medium"
        type="button"
        tabindex="-1"
        variant="ghost"
        @click="emit('edit')"
      >
        {{ player.name }}
        <span
          class="text-zinc-400 transition-opacity"
          :class="{
            'opacity-0': !gameStore.isInSensitiveMode,
            'opacity-100': gameStore.isInSensitiveMode,
          }"
          >({{ player.role ? gameStore.roleDefByKeyMap[player.role].label : 'х/з' }})</span
        >
        <Icon
          title="icon-[tabler--pencil]"
          class="size-4 opacity-0 transition-opacity group-hover:opacity-60 group-focus:opacity-60"
        />
      </Button>
    </header>
    <!-- <div
      v-if="!player.isAlive"
      class="absolute top-1/2 -left-2 h-px w-[calc(100%+1rem)] bg-zinc-300"
    /> -->
    <div class="flex h-full items-center px-2">
      <slot v-if="player.isAlive" name="content" :player="player" />
    </div>
    <footer class="flex items-center gap-2 overflow-auto">
      <template
        v-if="
          activeEffects.length &&
          player.isAlive &&
          (gameStore.isNightRoleTurn || gameStore.isNightResults)
        "
      >
        <span
          v-for="effect in activeEffects"
          :key="effect.key"
          :class="[
            'rounded-full border px-2 py-0.5 text-xs',
            {
              'border-green-500/40 bg-green-500/10 text-green-600 dark:text-green-300':
                effect.quality === 'positive',
              'border-zinc-500/40 bg-zinc-500/10 text-zinc-600 dark:text-zinc-300':
                effect.quality === 'neutral',
              'border-amber-500/40 bg-amber-500/10 text-amber-600 dark:text-amber-300':
                effect.quality === 'negative',
              'border-red-500/40 bg-red-500/10 text-red-600 dark:text-red-300':
                effect.quality === 'damage',
            },
          ]"
        >
          {{ effect.label }}
        </span>
      </template>
      <slot v-if="player.isAlive" name="actions" :player="player" />
      <div v-else class="mr-2 text-sm opacity-30">RIP</div>
    </footer>
  </article>
</template>

<script setup lang="ts">
import PlayerEditForm from './PlayerEditForm.vue'
import { computed, ref } from 'vue'
import type { PlayerSlot } from '@processes/game-session'
import { EFFECTS } from '@shared/config/effects'
import { ROLE_DEFINITIONS } from '@shared/config/roles'
import { useGameStore } from '@/app/stores/gameStore'

interface Props {
  player: PlayerSlot
  showRole?: boolean
  isEditing?: boolean
}

interface Emits {
  (e: 'update:name', payload: { player: PlayerSlot; name: string }): void
  (e: 'edit'): void
  (e: 'cancel-edit'): void
}

const props = defineProps<Props>()
const emit = defineEmits<Emits>()
const gameStore = useGameStore()

const statusLabel = computed(() => (props.player.isAlive ? 'В игре' : 'Выбыл'))
const statusClass = computed(() =>
  props.player.isAlive
    ? 'bg-emerald-500/15 text-emerald-300 border border-emerald-500/40'
    : 'bg-rose-500/15 text-rose-300 border border-rose-500/40',
)

const roleLabel = computed(() => {
  if (!props.showRole) {
    return null
  }

  const role = ROLE_DEFINITIONS.find((definition) => definition.key === props.player.role)
  return role?.label ?? props.player.role
})

const activeEffects = computed(() => props.player.effects.map((effect) => EFFECTS[effect]))

const setVote = (playerId: string, value: number) => {
  gameStore.setVote(playerId, Number.isFinite(value) ? Math.max(0, value) : 0)
}

const handleSubmit = (player: PlayerSlot) => {
  emit('update:name', { player, name: player.name })
}
</script>
