import type { PersistedGameSession } from '@shared/lib/storage/gameSessionStorage'
import {
  compressToEncodedURIComponent,
  decompressFromEncodedURIComponent,
} from 'lz-string'

const SNAPSHOT_VERSION = 1

type SharedSnapshotPayload = {
  version: number
  session: PersistedGameSession
}

type NodeBuffer = {
  from: (input: string, encoding: string) => { toString: (encoding: string) => string }
} | null

const binaryFromString = (input: string): string => {
  const encoder = new TextEncoder()
  const bytes = encoder.encode(input)
  let result = ''
  const chunkSize = 0x8000

  for (let index = 0; index < bytes.length; index += chunkSize) {
    result += String.fromCharCode(...bytes.subarray(index, index + chunkSize))
  }

  return result
}

const stringFromBinary = (binary: string): string => {
  const bytes = new Uint8Array(binary.length)

  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index)
  }

  const decoder = new TextDecoder()
  return decoder.decode(bytes)
}

const getNodeBuffer = (): NodeBuffer => {
  const maybeBuffer = (globalThis as typeof globalThis & { Buffer?: NodeBuffer }).Buffer
  if (!maybeBuffer) {
    return null
  }
  return maybeBuffer
}

const encodeBase64 = (input: string): string => {
  if (typeof globalThis.btoa === 'function') {
    return globalThis.btoa(binaryFromString(input))
  }

  const buffer = getNodeBuffer()
  if (buffer) {
    return buffer.from(input, 'utf-8').toString('base64')
  }

  throw new Error('Base64 encoding is not supported in this environment')
}

const decodeBase64 = (input: string): string => {
  if (typeof globalThis.atob === 'function') {
    return stringFromBinary(globalThis.atob(input))
  }

  const buffer = getNodeBuffer()
  if (buffer) {
    return buffer.from(input, 'base64').toString('utf-8')
  }

  throw new Error('Base64 decoding is not supported in this environment')
}

const toUrlSafe = (base64: string): string =>
  base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/u, '')

const fromUrlSafe = (urlSafe: string): string => {
  const base64 = urlSafe.replace(/-/g, '+').replace(/_/g, '/')
  const padding = base64.length % 4 === 0 ? '' : '='.repeat(4 - (base64.length % 4))
  return base64 + padding
}

const parsePayload = (json: string): SharedSnapshotPayload | null => {
  try {
    const payload = JSON.parse(json) as Partial<SharedSnapshotPayload>
    if (typeof payload !== 'object' || payload === null) {
      return null
    }

    if (typeof payload.version !== 'number' || payload.version < 1) {
      return null
    }

    if (!payload.session || typeof payload.session !== 'object') {
      return null
    }

    return payload as SharedSnapshotPayload
  } catch {
    return null
  }
}

const decodeCompressedPayload = (encoded: string): SharedSnapshotPayload | null => {
  const json = decompressFromEncodedURIComponent(encoded)
  if (!json) {
    return null
  }
  return parsePayload(json)
}

const decodeLegacyPayload = (encoded: string): SharedSnapshotPayload | null => {
  try {
    const base64 = fromUrlSafe(encoded)
    const json = decodeBase64(base64)
    return parsePayload(json)
  } catch {
    return null
  }
}

export const encodeSnapshot = (session: PersistedGameSession): string => {
  const payload: SharedSnapshotPayload = {
    version: SNAPSHOT_VERSION,
    session,
  }
  const json = JSON.stringify(payload)
  return compressToEncodedURIComponent(json)
}

export const decodeSnapshot = (encoded: string): PersistedGameSession | null => {
  const compressedPayload = decodeCompressedPayload(encoded)
  if (compressedPayload) {
    return compressedPayload.session
  }

  const legacyPayload = decodeLegacyPayload(encoded)
  if (legacyPayload) {
    return legacyPayload.session
  }

  return null
}
