<template>
  <main class="min-h-screen" :class="gameStore.isLightOff && 'dark bg-zinc-900'">
    <div class="container mx-auto flex h-screen min-h-screen flex-col gap-8">
      <StartScreen v-if="currentView === 'start'" class="h-full" @start="handleStart" />
      <ConfigScreen
        v-else-if="currentView === 'config'"
        @configured="handleConfigured"
        @canceled="handleConfigCancel"
      />
      <VictoryScreen
        v-else-if="currentView === 'victory'"
        :victory="lastVictory"
        @restart="handleVictoryRestart"
        @reset="handleVictoryReset"
      />
      <GameScreen
        v-else
        :role-configs="configuredRoles"
        :initial-players="initialPlayers"
        @reset="handleGameReset"
        @finish="handleGameFinish"
      />
    </div>
  </main>
</template>

<script setup lang="ts">
import { useGameStore } from '@/app/stores/gameStore'
import { useGameKeyboardShortcuts } from '@features/game/keyboard-shortcuts'
import { ConfigScreen } from '@pages/config'
import { StartScreen } from '@pages/start'
import { VictoryScreen } from '@pages/victory'
import type { PlayerSlot, RoleConfig, VictoryResult } from '@processes/game-session'
import { storeToRefs } from 'pinia'
import { computed, ref, watch } from 'vue'
import { GameScreen } from './ui'

type View = 'start' | 'config' | 'game' | 'victory'

const currentView = ref<View>('start')
const configuredRoles = ref<RoleConfig[]>([])
const initialPlayers = ref<PlayerSlot[]>([])
const lastVictory = ref<VictoryResult | null>(null)
const gameStore = useGameStore()
const {
  canContinue,
  canUndo,
  canRedo,
  players: storePlayers,
  roleConfigs: storeRoleConfigs,
  victory: storeVictory,
  isGameOver,
} = storeToRefs(gameStore)

useGameKeyboardShortcuts({
  nextStage: {
    tryAutoAdvanceStage: () => gameStore.tryAutoAdvanceStage(),
    continueStage: () => gameStore.continueStage(),
    canContinue: () => Boolean(canContinue.value),
  },
  history: {
    undo: () => {
      void gameStore.undo()
    },
    redo: () => {
      void gameStore.redo()
    },
    canUndo: () => Boolean(canUndo.value),
    canRedo: () => Boolean(canRedo.value),
  },
})

let playerCounter = 1
const hasAppliedPersistedView = ref(false)

const normalizePlayers = (playersList: PlayerSlot[]): PlayerSlot[] =>
  playersList.map((player) => ({
    ...player,
    isAlive: player.isAlive ?? true,
    canSpeak: player.canSpeak ?? true,
    effects: Array.isArray(player.effects) ? [...player.effects] : [],
  }))

const applyStoreSessionToView = () => {
  if (hasAppliedPersistedView.value) {
    return
  }

  const currentPlayers = normalizePlayers(storePlayers.value)
  if (!currentPlayers.length) {
    return
  }

  const currentRoleConfigs = (storeRoleConfigs.value ?? []).map((config) => ({ ...config }))

  configuredRoles.value = currentRoleConfigs
  initialPlayers.value = currentPlayers
  playerCounter = currentPlayers.length > 0 ? currentPlayers.length + 1 : 1
  if (isGameOver.value) {
    lastVictory.value = storeVictory.value ?? null
    currentView.value = 'victory'
  } else {
    lastVictory.value = storeVictory.value ?? null
    currentView.value = 'game'
  }
  hasAppliedPersistedView.value = true
}

watch(
  () => gameStore.hasPersistedSession,
  (isPersisted) => {
    if (!isPersisted) {
      hasAppliedPersistedView.value = false
      return
    }
    applyStoreSessionToView()
  },
  { immediate: true },
)

watch(
  [storePlayers, storeRoleConfigs],
  () => applyStoreSessionToView(),
  { deep: true },
)

const generatePlayers = (configs: RoleConfig[]): PlayerSlot[] => {
  const players: PlayerSlot[] = []
  let names = [
    'Алексей',
    'Борис',
    'Виктор',
    'Григорий',
    'Дмитрий',
    'Евгений',
    'Женя',
    'Захар',
    'Иван',
    'Константин',
    'Леонид',
    'Максим',
    'Николай',
    'Олег',
    'Павел',
    'Роман',
    'Сергей',
    'Тимофей',
    'Федор',
    'Юрий',
  ]
  configs.forEach((config) => {
    for (let index = 0; index < config.quantity; index += 1) {
      const id = `player-${playerCounter++}`
      const randomIndex = Math.floor(Math.random() * names.length)
      const name = names[randomIndex]
      names = names.filter((_, i) => i !== randomIndex)
      players.push({
        id,
        name,
        role: null,
        isAlive: true,
        canSpeak: true,
        effects: [],
        haveGoldenMinute: true,
      })
    }
  })

  return players
}

const clearSessionState = () => {
  configuredRoles.value = []
  initialPlayers.value = []
  playerCounter = 1
  lastVictory.value = null
}

const handleStart = () => {
  currentView.value = 'config'
}

const handleConfigCancel = () => {
  currentView.value = 'start'
}

const handleConfigured = (configs: RoleConfig[]) => {
  configuredRoles.value = configs
  initialPlayers.value = generatePlayers(configs)
  lastVictory.value = null
  currentView.value = 'game'
}

const handleGameReset = () => {
  clearSessionState()
  currentView.value = 'start'
}

const handleGameFinish = (result: VictoryResult | null) => {
  lastVictory.value = result
  currentView.value = 'victory'
}

const handleVictoryRestart = () => {
  gameStore.resetGame()
  clearSessionState()
  currentView.value = 'config'
}

const handleVictoryReset = () => {
  gameStore.resetGame()
  clearSessionState()
  currentView.value = 'start'
}

const showHeader = computed(() => currentView.value !== 'start')

watch(
  storeVictory,
  (victory) => {
    if (currentView.value === 'victory') {
      lastVictory.value = victory ?? null
    }
  },
  { immediate: false },
)
</script>
