import { useGameStore } from '@/app/stores/gameStore'
import { RoleKey, PlayerSlot } from '@/processes/game-session'
import { ROLE_DEFINITIONS, GroupDictionary } from '@/shared/config/roles'
import { defineStore } from 'pinia'
import { ref, computed, toRaw } from 'vue'
import { toPng } from 'html-to-image'

export const useGameHistory = defineStore('gameHistory', () => {
  const game = useGameStore()
  const isDialogOpen = computed(() => Boolean(game.isHistoryDialogOpen))

  const handleDialogToggle = (open: boolean) => {
    if (!open && game.isHistoryDialogOpen) {
      game.isHistoryDialogOpen = false
    }
  }

  const historyRows = computed(() => {
    const playerById = new Map(game.players.map((player) => [player.id, player]))
    const sortedHistory = [...game.history].sort((a, b) => a.timestamp - b.timestamp)

    return sortedHistory.map((entry) => {
      const roleDefinition = entry.role
        ? ROLE_DEFINITIONS.find((definition) => definition.key === entry.role)
        : null
      const targetPlayer = entry.targetId ? (playerById.get(entry.targetId) ?? null) : null
      const group = GroupDictionary[entry.group]
      const timestamp = new Date(entry.timestamp)

      return {
        id: entry.id,
        roleLabel: roleDefinition?.label ?? group?.title ?? entry.group ?? '—',
        players: roleDefinition?.key ? game.playerByRoleMap[roleDefinition.key] : [],
        groupLabel: group?.title ?? entry.group,
        action: entry.action,
        effectQuality: entry.effectQuality,
        targetName: targetPlayer?.name ?? (entry.targetId ? 'Неизвестно' : '—'),
        targetId: targetPlayer?.id ?? entry.targetId ?? null,
        timestamp: timestamp.toLocaleTimeString('ru-RU'),
        isFatal: entry.isFatal,
        dayCount: entry.dayCount,
      }
    })
  })

  const deepClone = <T>(value: T): T => {
    if (value === null || typeof value !== 'object') {
      return value
    }

    const rawValue = toRaw(value) as T

    if (typeof structuredClone === 'function') {
      try {
        return structuredClone(rawValue)
      } catch {
        // fallback to JSON below
      }
    }

    return JSON.parse(JSON.stringify(rawValue)) as T
  }

  const initialConfiguration = ref({
    roleConfigs: deepClone(game.roleConfigs),
    players: deepClone(game.players),
  })

  const buildHistoryExportPayload = () => ({
    version: 1,
    generatedAt: new Date().toISOString(),
    stage: game.currentStageKey,
    dayCount: game.dayCount,
    initialConfiguration: deepClone(initialConfiguration.value),
    currentState: {
      roleConfigs: deepClone(game.roleConfigs),
      players: deepClone(game.players),
    },
    history: deepClone(game.history),
  })

  const formatExportFileName = (extension: string) => {
    const now = new Date()
    const pad = (value: number) => value.toString().padStart(2, '0')
    const date = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}`
    const time = `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`
    return `game-history-${date}-${time}.${extension}`
  }

  const handleExportHistory = () => {
    if (typeof window === 'undefined') {
      return
    }

    const payload = buildHistoryExportPayload()
    const json = JSON.stringify(payload, null, 2)
    const blob = new Blob([json], { type: 'application/json' })
    const url = window.URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = formatExportFileName('json')
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    window.URL.revokeObjectURL(url)
  }

  const handleExportHistoryImage = async (element: HTMLElement | null) => {
    if (typeof window === 'undefined' || !element) {
      return
    }

    const padding = 24
    const contentWidth = element.scrollWidth
    const contentHeight = element.scrollHeight
    const clone = element.cloneNode(true) as HTMLElement
    clone.style.boxSizing = 'border-box'
    clone.style.width = `${contentWidth}px`

    const container = document.createElement('div')
    const hiddenRoot = document.createElement('div')

    container.style.padding = `${padding}px`
    container.style.backgroundColor = '#ffffff'
    container.style.display = 'inline-block'
    container.style.boxSizing = 'border-box'

    hiddenRoot.style.position = 'fixed'
    hiddenRoot.style.left = '-9999px'
    hiddenRoot.style.top = '0'
    hiddenRoot.style.pointerEvents = 'none'
    hiddenRoot.style.opacity = '0'
    hiddenRoot.style.backgroundColor = '#ffffff'

    container.appendChild(clone)
    hiddenRoot.appendChild(container)
    document.body.appendChild(hiddenRoot)

    const width = contentWidth + padding * 2
    const height = contentHeight + padding * 2

    try {
      const dataUrl = await toPng(container, {
        cacheBust: true,
        pixelRatio: Math.min(window.devicePixelRatio || 1, 2),
        backgroundColor: '#ffffff',
        width,
        height,
      })

      const link = document.createElement('a')
      link.href = dataUrl
      link.download = formatExportFileName('png')
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    } catch (error) {
      console.error('Failed to export history as image', error)
    } finally {
      document.body.removeChild(hiddenRoot)
    }
  }

  return {
    isDialogOpen,
    handleDialogToggle,
    historyRows,
    handleExportHistory,
    handleExportHistoryImage,
  }
})
