<template>
  <div class="relative flex w-full overflow-hidden rounded-xl border px-2 py-1 dark:text-white">
    <audio
      v-if="audioSrc"
      ref="audioRef"
      :src="audioSrc"
      class="hidden"
      v-bind="{ autoplay }"
      @loadedmetadata="onLoadedMetadata"
      @timeupdate="onTimeUpdate"
      @play="onPlay"
      @pause="onPause"
      @ended="onEnded"
    />

    <div class="abolute top-0 left-0 z-20 grid size-full w-full grid-cols-3">
      <div class="self-center justify-self-start">
        <button
          v-if="!!audioSrc"
          type="button"
          class="font-mono text-xs opacity-70"
          @click="toggleTimeDisplay"
        >
          {{ timelineLabel }}
        </button>
      </div>
      <div class="flex flex-1 items-center justify-center gap-2">
        <button
          type="button"
          :class="[
            'flex items-center justify-center rounded-xl border border-zinc-200 bg-white/85 p-1 text-zinc-700 backdrop-blur-2xl transition hover:border-zinc-800 hover:bg-zinc-800 hover:text-white',
            'dark:border-zinc-700 dark:bg-zinc-800/85 dark:text-zinc-200 dark:hover:bg-zinc-600',
            'disabled:pointer-events-none disabled:bg-zinc-50 disabled:opacity-70',
          ]"
          :disabled="!audioSrc"
          @click="seekBy(-10)"
        >
          <Icon title="icon-[tabler--rewind-backward-10]" class="size-4" />
        </button>

        <button
          type="button"
          :class="[
            'flex items-center justify-center rounded-xl border border-zinc-200 bg-white/85 p-2 text-zinc-700 backdrop-blur-2xl transition hover:border-zinc-800 hover:bg-zinc-800 hover:text-white',
            'dark:border-zinc-700 dark:bg-zinc-800/85 dark:text-zinc-200 dark:hover:bg-zinc-600',
            'disabled:pointer-events-none disabled:bg-zinc-50 disabled:opacity-70',
          ]"
          :disabled="!audioSrc"
          @click="togglePlayback"
        >
          <Icon v-if="isPlaying" title="icon-[tabler--player-pause-filled]" class="size-4" />
          <Icon v-else title="icon-[tabler--player-play-filled]" class="size-4" />
        </button>

        <button
          type="button"
          :class="[
            'flex items-center justify-center rounded-xl border border-zinc-200 bg-white/85 p-1 text-zinc-700 backdrop-blur-2xl transition hover:border-zinc-800 hover:bg-zinc-800 hover:text-white',
            'dark:border-zinc-700 dark:bg-zinc-800/85 dark:text-zinc-200 dark:hover:bg-zinc-600',
            'disabled:pointer-events-none disabled:bg-zinc-50 disabled:opacity-70',
          ]"
          :disabled="!audioSrc"
          @click="seekBy(10)"
        >
          <Icon title="icon-[tabler--rewind-forward-10]" class="size-4" />
        </button>
      </div>
    </div>
    <div
      :class="[
        'absolute top-0 left-0 z-0 size-full bg-amber-50 dark:bg-zinc-800',
        {
          'bg-zinc-100': !audioSrc,
        },
      ]"
    />
    <div
      class="absolute top-0 left-0 z-10 size-full bg-amber-400 dark:bg-red-600/40"
      :style="{ width: progressBarWidth }"
    />
  </div>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { animate } from 'animejs'

import { useGameStore } from '@/app/stores/gameStore'
import { audioController } from '@/shared/lib/audio/audioController'
import { resolveInternalLink } from '@/shared/lib/utils';

const props = defineProps<{
  src?: string | null
  autoplay?: boolean
}>()

const game = useGameStore()

const audioRef = ref<HTMLAudioElement | null>(null)
const isPlaying = ref(false)
const currentTime = ref(0)
const duration = ref(0)
const showRemaining = ref(false)

const hasExternalSrc = computed(() => props.src !== undefined)

const normalizeSrc = (value: string | null | undefined): string | null => {
  if (!value) {
    return null
  }

  if (/^(?:https?:)?\/\//u.test(value) || value.startsWith('/')) {
    return value
  }

  return resolveInternalLink(`/audio/${value}`)
}

const audioSrc = computed(() => {
  if (props.src !== undefined) {
    return normalizeSrc(props.src)
  }
  return normalizeSrc(game.currentAudioTitle)
})

const autoplay = computed(() => {
  if (hasExternalSrc.value) {
    return props.autoplay ?? false
  }

  return !!audioSrc.value && game.stageInfo?.autoPlay !== false
})

const progress = computed(() => {
  if (!duration.value) return 0
  return Math.min(Math.max(currentTime.value / duration.value, 0), 1)
})

const progressBarWidth = ref('0%')
const progressProxy: { value: number } = { value: 0 }
let progressAnimation: ReturnType<typeof animate> | null = null
let progressInitialized = false
let unregisterPlaybackController: (() => void) | null = null

const timelineLabel = computed(() => {
  const baseDuration = duration.value || 0
  const remaining = Math.max(baseDuration - currentTime.value, 0)
  const seconds = showRemaining.value ? remaining : currentTime.value
  const prefix = showRemaining.value ? '-' : ''
  return `${prefix}${formatTime(seconds)}`
})

const clampProgress = (value: number) =>
  Math.min(Math.max(Number.isFinite(value) ? value : 0, 0), 1)

const updateProgressWidth = (value: number) => {
  progressBarWidth.value = `${(clampProgress(value) * 100).toFixed(2)}%`
}

const resetProgressAnimation = () => {
  if (progressAnimation) {
    progressAnimation.pause()
    progressAnimation = null
  }
  progressInitialized = false
  progressProxy.value = 0
  updateProgressWidth(0)
}

watch(
  progress,
  (value) => {
    const targetValue = clampProgress(value)

    if (!progressInitialized) {
      progressInitialized = true
      progressProxy.value = targetValue
      updateProgressWidth(targetValue)
      return
    }

    if (Math.abs(progressProxy.value - targetValue) < 0.0001) {
      progressProxy.value = targetValue
      updateProgressWidth(targetValue)
      return
    }

    if (progressAnimation) {
      progressAnimation.pause()
    }

    progressAnimation = animate(progressProxy, {
      value: targetValue,
      duration: 350,
      ease: 'easeOutQuad',
      onUpdate: () => {
        updateProgressWidth(progressProxy.value)
      },
      onComplete: () => {
        progressAnimation = null
        progressProxy.value = targetValue
        updateProgressWidth(targetValue)
      },
    })
  },
  { immediate: true },
)

watch(audioSrc, async (src) => {
  currentTime.value = 0
  duration.value = 0
  isPlaying.value = false
  showRemaining.value = false
  resetProgressAnimation()

  if (!audioRef.value) return

  audioRef.value.currentTime = 0
  if (!src) {
    audioRef.value.pause()
    return
  }

  audioRef.value.pause()

  if (autoplay.value) {
    await nextTick()
    const playPromise = audioRef.value.play()
    if (playPromise) {
      playPromise.catch(() => {
        // Autoplay can be blocked by the browser; ignore the rejection.
      })
    }
  }
})

const togglePlayback = () => {
  const audio = audioRef.value
  if (!audio) return

  if (isPlaying.value) {
    audio.pause()
    return
  }

  const playPromise = audio.play()
  if (playPromise) {
    playPromise.catch(() => {
      // Playback promise can reject (e.g., autoplay restrictions); ignore.
    })
  }
}

const seekBy = (seconds: number) => {
  const audio = audioRef.value
  if (!audio) return

  const baseDuration = duration.value || audio.duration || 0
  const nextTime = Math.min(Math.max(audio.currentTime + seconds, 0), baseDuration)
  audio.currentTime = nextTime
  currentTime.value = nextTime
}

const toggleTimeDisplay = () => {
  if (!duration.value) return
  showRemaining.value = !showRemaining.value
}

const onLoadedMetadata = () => {
  const audio = audioRef.value
  if (!audio) return

  duration.value = audio.duration || 0
}

const onTimeUpdate = () => {
  const audio = audioRef.value
  if (!audio) return

  currentTime.value = audio.currentTime
}

const onPlay = () => {
  isPlaying.value = true
}

const onPause = () => {
  isPlaying.value = false
}

const onEnded = () => {
  isPlaying.value = false
  currentTime.value = duration.value

  if (!hasExternalSrc.value && game.stageInfo?.autoNext && game.canAutoAdvanceStage) {
    game.tryAutoAdvanceStage()
  }
}

const formatTime = (totalSeconds: number) => {
  const safeSeconds = Math.max(totalSeconds, 0)
  const minutes = Math.floor(safeSeconds / 60)
  const seconds = Math.floor(safeSeconds % 60)
  return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
}

onMounted(() => {
  unregisterPlaybackController = audioController.register(() => audioRef.value)
})

onBeforeUnmount(() => {
  if (unregisterPlaybackController) {
    unregisterPlaybackController()
    unregisterPlaybackController = null
  }
})
</script>
