<template>
  <form class="flex w-full" @submit.prevent="emit('submit', model)" ref="root">
    <Input
      v-model.trim="model.name"
      type="text"
      placeholder="Введите имя"
      class="!border-none !shadow-none !ring-0 font-medium"
      autofocus
    />

    <Button
      tabindex="-1"
      type="submit"
      variant="ghost"
      class="inline-flex items-center gap-2 rounded-md px-3 py-1 text-xs font-semibold text-emerald-500 transition hover:bg-emerald-200 hover:text-emerald-500"
    >
      Готово
    </Button>
    <Button
      tabindex="-1"
      type="button"
      variant="ghost"
      class="inline-flex items-center gap-2 rounded-md px-3 py-1 text-xs font-medium text-red-500 hover:bg-red-200 hover:text-red-500 -mr-2"
      @click="emit('cancel', model)"
    >
      Отмена
    </Button>
  </form>
</template>

<script setup lang="ts">
import { Button, Input } from '@/shared/ui'
import { PlayerSlot } from '@/processes/game-session'
import { onMounted, ref } from 'vue'

type Props = {
  modelValue: PlayerSlot
}

type Emits = {
  (e: 'submit', value: PlayerSlot): void
  (e: 'cancel', value: PlayerSlot): void
}
const props = defineProps<Props>()
const emit = defineEmits<Emits>()

const model = ref<PlayerSlot>({ ...props.modelValue })
const root = ref<HTMLElement | null>(null)

onMounted(() => {
  root.value?.querySelector('input')?.focus()
})
</script>
